/**
 * Electron, mass, and charge bookkeeping.
 *
 * These are COUNTERS, not checks. Nothing in this file decides whether a
 * structure is right. It reports totals; `packages/validators` compares them and
 * decides. Keeping the counting here and the deciding there is what makes the
 * checks falsifiable: a validator that computed its own totals would be grading
 * its own arithmetic.
 *
 * Counting lives in chem-core because D3 gives chem-core exactly this job, in
 * the browser, inside the hundred millisecond budget.
 *
 * MASS IS COUNTED AS NUCLEI, NOT AS WEIGHT. Summing atomic weights and comparing
 * floats needs a tolerance, and a tolerance is a thing somebody widens at 2am to
 * make a fixture pass. A multiset of nuclide keys compares exactly.
 */

import type { Atom } from "./atom.js";
import { atomNuclideKey, nonbondingElectrons, nuclideKey } from "./atom.js";
import type { Species } from "./species.js";
import { bondsAt, requireAtom } from "./species.js";
import { elementProperties } from "./elements.js";
import type { AtomId } from "./ids.js";
import type { MechanismState } from "./state.js";
import { participatingMembers } from "./state.js";

/** A multiset of nuclei, keyed as in `nuclideKey`. */
export type NuclideCounts = Readonly<Record<string, number>>;

const HYDROGEN_KEY = nuclideKey("H");

function addTo(counts: Record<string, number>, key: string, amount: number): void {
  counts[key] = (counts[key] ?? 0) + amount;
}

/**
 * Every nucleus in a species, including implicit hydrogens.
 *
 * The implicit hydrogen term is the one that matters. VERIFICATION.md S5
 * describes the bug exactly: a proton transfer changes implicit hydrogen counts
 * on two atoms and touches nothing else, so a mass count that walks only the
 * explicit atom list reports conservation while a proton quietly appeared or
 * vanished.
 */
export function nuclideCounts(species: Species): NuclideCounts {
  const counts: Record<string, number> = {};
  for (const atom of species.atoms) {
    addTo(counts, atomNuclideKey(atom), 1);
    if (atom.implicitHydrogens !== 0) {
      addTo(counts, HYDROGEN_KEY, atom.implicitHydrogens);
    }
  }
  return counts;
}

/** Nuclei across a set of species. */
export function nuclideCountsOfMany(speciesList: readonly Species[]): NuclideCounts {
  const counts: Record<string, number> = {};
  for (const species of speciesList) {
    for (const [key, value] of Object.entries(nuclideCounts(species))) {
      addTo(counts, key, value);
    }
  }
  return counts;
}

/**
 * Standard atomic weight of a species, for display only.
 *
 * Never use this for conservation. It is here so a debug view can show a mass
 * and so a wildly wrong structure is obvious at a glance. Isotopes are counted
 * at their mass number, which is an approximation and is fine for a label.
 */
export function approximateMass(species: Species): number {
  let total = 0;
  for (const atom of species.atoms) {
    total +=
      atom.isotope === undefined ? elementProperties(atom.element).standardAtomicWeight : atom.isotope;
    total += atom.implicitHydrogens * elementProperties("H").standardAtomicWeight;
  }
  return total;
}

/**
 * A molecular formula in Hill order: carbon, then hydrogen, then everything else
 * alphabetically. Debug and display only. Isotopes are folded into their element
 * here, so it is not an identity.
 */
export function molecularFormula(species: Species): string {
  const counts: Record<string, number> = {};
  for (const atom of species.atoms) {
    addTo(counts, atom.element, 1);
    if (atom.implicitHydrogens !== 0) {
      addTo(counts, "H", atom.implicitHydrogens);
    }
  }

  const symbols = Object.keys(counts).sort();
  const ordered: string[] = [];
  if (counts["C"] !== undefined) ordered.push("C");
  if (counts["H"] !== undefined) ordered.push("H");
  for (const symbol of symbols) {
    if (symbol !== "C" && symbol !== "H") ordered.push(symbol);
  }

  return ordered
    .map((symbol) => {
      const count = counts[symbol] ?? 0;
      return count === 1 ? symbol : `${symbol}${count}`;
    })
    .join("");
}

/**
 * Sum of bond orders at an atom, counting implicit hydrogens as order one.
 *
 * Forgetting the implicit hydrogen term here makes every methyl group look like
 * a carbanion, so it is folded in rather than left to the caller.
 */
export function bondOrderSumAt(species: Species, atomId: AtomId): number {
  const atom = requireAtom(species, atomId);
  let total = atom.implicitHydrogens;
  for (const bond of bondsAt(species, atomId)) {
    total += bond.order;
  }
  return total;
}

/**
 * The formal charge the structure implies, as opposed to the one declared.
 *
 * formalCharge = valenceElectrons - nonbondingElectrons - bondOrderSum
 *
 * When this disagrees with `atom.formalCharge`, one of the two is wrong and
 * `formal_charge_disagrees_with_structure` is the named cause. This function
 * reports the number; it does not decide which is at fault.
 */
export function derivedFormalCharge(species: Species, atomId: AtomId): number {
  const atom = requireAtom(species, atomId);
  const properties = elementProperties(atom.element);
  return properties.valenceElectrons - nonbondingElectrons(atom) - bondOrderSumAt(species, atomId);
}

/**
 * Valence electrons around an atom, the number the octet rule is about.
 *
 * Bonding electrons are counted in full at both ends, which is the octet
 * convention rather than the formal charge convention. The two counts answer
 * different questions and mixing them up is a classic source of a check that
 * fires on correct structures.
 */
export function valenceElectronsAround(species: Species, atomId: AtomId): number {
  const atom = requireAtom(species, atomId);
  return nonbondingElectrons(atom) + bondOrderSumAt(species, atomId) * 2;
}

/** Declared charge on a species: the sum of its atoms' declared formal charges. */
export function speciesCharge(species: Species): number {
  return species.atoms.reduce((total, atom) => total + atom.formalCharge, 0);
}

/**
 * Total valence electrons in a species.
 *
 * Neutral atom contributions minus the charge. An implicit hydrogen brings one.
 * A positive charge means one electron fewer than the neutral atoms would have
 * had, which is why charge is subtracted.
 */
export function valenceElectronCount(species: Species): number {
  let total = 0;
  for (const atom of species.atoms) {
    total += elementProperties(atom.element).valenceElectrons;
    total += atom.implicitHydrogens * elementProperties("H").valenceElectrons;
  }
  return total - speciesCharge(species);
}

/**
 * The three quantities conservation is asserted over, totalled across the
 * multiset.
 *
 * This is the system boundary rule as a single function call. Spectators are
 * excluded by default, because that is what declaring a spectator means; pass
 * `includeSpectators` to get the totals over everything, which is what an
 * adversary attacking a spectator declaration wants.
 */
export interface ConservedTotals {
  readonly nuclides: NuclideCounts;
  readonly charge: number;
  readonly valenceElectrons: number;
  /** Which species were counted. Recorded so a failure can say what was in scope. */
  readonly countedSpeciesIds: readonly string[];
}

export interface ConservedTotalsOptions {
  readonly includeSpectators?: boolean;
}

export function conservedTotals(
  state: MechanismState,
  options: ConservedTotalsOptions = {},
): ConservedTotals {
  const members = options.includeSpectators === true ? state.members : participatingMembers(state);
  const speciesList = members.map((member) => member.species);

  let charge = 0;
  let electrons = 0;
  for (const species of speciesList) {
    charge += speciesCharge(species);
    electrons += valenceElectronCount(species);
  }

  return Object.freeze({
    nuclides: nuclideCountsOfMany(speciesList),
    charge,
    valenceElectrons: electrons,
    countedSpeciesIds: Object.freeze(speciesList.map((species) => species.id)),
  });
}

/**
 * Compare two nuclide multisets. Empty result means they match exactly.
 *
 * Returned as a difference rather than a boolean so a failure can say "one
 * hydrogen short" instead of "mass not conserved".
 */
export function nuclideDifference(before: NuclideCounts, after: NuclideCounts): NuclideCounts {
  const difference: Record<string, number> = {};
  const keys = new Set<string>([...Object.keys(before), ...Object.keys(after)]);
  for (const key of keys) {
    const delta = (after[key] ?? 0) - (before[key] ?? 0);
    if (delta !== 0) {
      difference[key] = delta;
    }
  }
  return difference;
}

/** Convenience for reading an atom's nuclide key without a species lookup. */
export function atomKey(atom: Atom): string {
  return atomNuclideKey(atom);
}

src/deltas.ts.source:
/**
 * The two halves of the arrow check, computed independently.
 *
 * `declaredDeltas` reads the arrows and says what they CLAIM happened.
 * `observedDeltas` reads the two states and says what actually CHANGED.
 * A validator compares them. Neither function knows about the other, and neither
 * one is derived from the other, which is the only reason the comparison means
 * anything. See the note at the top of arrows.ts.
 *
 * EVERYTHING HERE IS COUNTED IN ELECTRONS, NOT IN BOND ORDERS.
 *
 * Two fishhook arrows into the same place make one bond. In bond orders that is
 * two changes of one half each, and half orders are a source of rounding
 * arguments nobody wants. In electrons it is two changes of one electron each,
 * and every number in this file is an integer.
 *
 * A bond order change of one is a bonding electron change of two.
 */

import type { ElectronFlowArrow } from "./arrows.js";
import { nonbondingElectrons } from "./atom.js";
import type { Atom } from "./atom.js";
import { atomPairKey, parseAtomPairKey } from "./bond.js";
import type { AtomId } from "./ids.js";
import type { MechanismState } from "./state.js";

/**
 * Change at one atom.
 *
 * `implicitHydrogens` is here and has no counterpart in `declaredDeltas`, on
 * purpose. Arrows cannot express a change in undrawn hydrogens, so any nonzero
 * value in the observed set with no explicit hydrogen atom to account for it is
 * the S5 bug caught in the act. The named cause is
 * `implicit_hydrogen_changed_without_arrow`.
 */
export interface AtomElectronDelta {
  readonly atomId: AtomId;
  /** Change in 2 * lonePairs + unpairedElectrons. */
  readonly nonbondingElectrons: number;
  /** Change in undrawn hydrogen count. Always 0 in a declared set. */
  readonly implicitHydrogens: number;
  /** Change in the declared formal charge. Reported, never asserted here. */
  readonly formalCharge: number;
}

/** Change in bonding electrons between two atoms. Two electrons is one order. */
export interface BondElectronDelta {
  readonly atomIds: readonly [AtomId, AtomId];
  readonly electrons: number;
}

export interface ElectronDeltaSet {
  readonly atoms: readonly AtomElectronDelta[];
  readonly bonds: readonly BondElectronDelta[];
  /** Atom ids in `from` with no counterpart in `to`. Empty in a declared set. */
  readonly atomsRemoved: readonly AtomId[];
  /** Atom ids in `to` with no counterpart in `from`. Empty in a declared set. */
  readonly atomsAdded: readonly AtomId[];
}

interface MutableAtomDelta {
  nonbondingElectrons: number;
  implicitHydrogens: number;
  formalCharge: number;
}

function emptyAtomDelta(): MutableAtomDelta {
  return { nonbondingElectrons: 0, implicitHydrogens: 0, formalCharge: 0 };
}

function atomDeltaFor(map: Map<AtomId, MutableAtomDelta>, atomId: AtomId): MutableAtomDelta {
  const existing = map.get(atomId);
  if (existing !== undefined) return existing;
  const created = emptyAtomDelta();
  map.set(atomId, created);
  return created;
}

function bumpBond(map: Map<string, number>, key: string, electrons: number): void {
  map.set(key, (map.get(key) ?? 0) + electrons);
}

function collectAtoms(state: MechanismState): Map<AtomId, Atom> {
  const atoms = new Map<AtomId, Atom>();
  for (const member of state.members) {
    for (const atom of member.species.atoms) {
      atoms.set(atom.id, atom);
    }
  }
  return atoms;
}

function collectBondElectrons(state: MechanismState): Map<string, number> {
  const bonds = new Map<string, number>();
  for (const member of state.members) {
    for (const bond of member.species.bonds) {
      bumpBond(bonds, atomPairKey(bond.a, bond.b), bond.order * 2);
    }
  }
  return bonds;
}

function assemble(
  atomDeltas: Map<AtomId, MutableAtomDelta>,
  bondDeltas: Map<string, number>,
  atomsRemoved: readonly AtomId[],
  atomsAdded: readonly AtomId[],
): ElectronDeltaSet {
  const atoms: AtomElectronDelta[] = [];
  for (const [atomId, delta] of atomDeltas) {
    if (
      delta.nonbondingElectrons === 0 &&
      delta.implicitHydrogens === 0 &&
      delta.formalCharge === 0
    ) {
      continue;
    }
    atoms.push(Object.freeze({ atomId, ...delta }));
  }

  const bonds: BondElectronDelta[] = [];
  for (const [key, electrons] of bondDeltas) {
    if (electrons === 0) continue;
    bonds.push(Object.freeze({ atomIds: parseAtomPairKey(key), electrons }));
  }

  atoms.sort((left, right) => left.atomId.localeCompare(right.atomId));
  bonds.sort((left, right) =>
    atomPairKey(left.atomIds[0], left.atomIds[1]).localeCompare(
      atomPairKey(right.atomIds[0], right.atomIds[1]),
    ),
  );

  return Object.freeze({
    atoms: Object.freeze(atoms),
    bonds: Object.freeze(bonds),
    atomsRemoved: Object.freeze([...atomsRemoved]),
    atomsAdded: Object.freeze([...atomsAdded]),
  });
}

/**
 * What the arrows claim.
 *
 * `state` is the `from` state of the step. It is needed only to turn a BondId
 * into the pair of atoms it joins, since a source arrow names the bond by id and
 * bond ids do not survive the step.
 *
 * Throws if an arrow names a bond that is not in the state. That is a broken
 * reference rather than a chemistry error, and a silent zero here would hide it.
 * The named cause `arrow_endpoint_not_in_state` is for the validator to raise
 * after checking references; this function assumes they resolve.
 */
export function declaredDeltas(
  arrows: readonly ElectronFlowArrow[],
  state: MechanismState,
): ElectronDeltaSet {
  const bondEnds = new Map<string, readonly [AtomId, AtomId]>();
  for (const member of state.members) {
    for (const bond of member.species.bonds) {
      bondEnds.set(bond.id, [bond.a, bond.b]);
    }
  }

  const atomDeltas = new Map<AtomId, MutableAtomDelta>();
  const bondDeltas = new Map<string, number>();

  for (const arrow of arrows) {
    const electrons = arrow.electrons;

    switch (arrow.source.kind) {
      case "lonePair":
      case "singleElectron": {
        atomDeltaFor(atomDeltas, arrow.source.atomId).nonbondingElectrons -= electrons;
        break;
      }
      case "bond": {
        const ends = bondEnds.get(arrow.source.bondId);
        if (ends === undefined) {
          throw new Error(
            `Arrow ${arrow.id} sources bond ${arrow.source.bondId}, which is not in state ${state.id}`,
          );
        }
        bumpBond(bondDeltas, atomPairKey(ends[0], ends[1]), -electrons);
        break;
      }
    }

    switch (arrow.sink.kind) {
      case "atom": {
        atomDeltaFor(atomDeltas, arrow.sink.atomId).nonbondingElectrons += electrons;
        break;
      }
      case "betweenAtoms": {
        const [a, b] = arrow.sink.atomIds;
        bumpBond(bondDeltas, atomPairKey(a, b), electrons);
        break;
      }
    }
  }

  return assemble(atomDeltas, bondDeltas, [], []);
}

/**
 * What actually changed between the two states.
 *
 * Atoms are matched by id across the step, which is the invariant stated in
 * ids.ts. An atom that appears on only one side is reported in `atomsAdded` or
 * `atomsRemoved` rather than treated as having changed from nothing, because
 * those two are a different failure with a different named cause.
 */
export function observedDeltas(from: MechanismState, to: MechanismState): ElectronDeltaSet {
  const before = collectAtoms(from);
  const after = collectAtoms(to);

  const atomDeltas = new Map<AtomId, MutableAtomDelta>();
  const atomsRemoved: AtomId[] = [];
  const atomsAdded: AtomId[] = [];

  for (const [atomId, beforeAtom] of before) {
    const afterAtom = after.get(atomId);
    if (afterAtom === undefined) {
      atomsRemoved.push(atomId);
      continue;
    }
    const delta = atomDeltaFor(atomDeltas, atomId);
    delta.nonbondingElectrons = nonbondingElectrons(afterAtom) - nonbondingElectrons(beforeAtom);
    delta.implicitHydrogens = afterAtom.implicitHydrogens - beforeAtom.implicitHydrogens;
    delta.formalCharge = afterAtom.formalCharge - beforeAtom.formalCharge;
  }

  for (const atomId of after.keys()) {
    if (!before.has(atomId)) {
      atomsAdded.push(atomId);
    }
  }

  const bondsBefore = collectBondElectrons(from);
  const bondsAfter = collectBondElectrons(to);
  const bondDeltas = new Map<string, number>();
  const keys = new Set<string>([...bondsBefore.keys(), ...bondsAfter.keys()]);
  for (const key of keys) {
    bondDeltas.set(key, (bondsAfter.get(key) ?? 0) - (bondsBefore.get(key) ?? 0));
  }

  atomsRemoved.sort();
  atomsAdded.sort();

  return assemble(atomDeltas, bondDeltas, atomsRemoved, atomsAdded);
}

/** One disagreement between what the arrows claimed and what the states show. */
export interface DeltaMismatch {
  readonly target:
    | { readonly kind: "atom"; readonly atomId: AtomId }
    | { readonly kind: "atomPair"; readonly atomIds: readonly [AtomId, AtomId] };
  readonly quantity: "nonbondingElectrons" | "bondingElectrons" | "implicitHydrogens";
  readonly declared: number;
  readonly observed: number;
}

/**
 * Every place the two sets disagree.
 *
 * Empty means the arrows fully account for the structural change. This function
 * reports the differences; deciding what they mean, and which named cause to
 * attach, is the validator's job.
 *
 * Note that `implicitHydrogens` is always declared as zero, because no arrow can
 * express it. A mismatch on that quantity is therefore always the observed value
 * standing alone, which is exactly the signal wanted.
 *
 * Formal charge deltas are carried on `AtomElectronDelta` but are NOT compared
 * here. An arrow says nothing about formal charge directly; the charge follows
 * from the electrons, and comparing it here would report the same single error
 * twice. Charge is checked against structure by `derivedFormalCharge`, and
 * across the step by `conservedTotals`.
 */
export function deltaMismatches(
  declared: ElectronDeltaSet,
  observed: ElectronDeltaSet,
): readonly DeltaMismatch[] {
  const mismatches: DeltaMismatch[] = [];

  const declaredAtoms = new Map<AtomId, AtomElectronDelta>(
    declared.atoms.map((delta) => [delta.atomId, delta]),
  );
  const observedAtoms = new Map<AtomId, AtomElectronDelta>(
    observed.atoms.map((delta) => [delta.atomId, delta]),
  );

  for (const atomId of new Set<AtomId>([...declaredAtoms.keys(), ...observedAtoms.keys()])) {
    const declaredAtom = declaredAtoms.get(atomId);
    const observedAtom = observedAtoms.get(atomId);
    const declaredNonbonding = declaredAtom?.nonbondingElectrons ?? 0;
    const observedNonbonding = observedAtom?.nonbondingElectrons ?? 0;
    if (declaredNonbonding !== observedNonbonding) {
      mismatches.push({
        target: { kind: "atom", atomId },
        quantity: "nonbondingElectrons",
        declared: declaredNonbonding,
        observed: observedNonbonding,
      });
    }
    const observedHydrogens = observedAtom?.implicitHydrogens ?? 0;
    if (observedHydrogens !== 0) {
      mismatches.push({
        target: { kind: "atom", atomId },
        quantity: "implicitHydrogens",
        declared: 0,
        observed: observedHydrogens,
      });
    }
  }

  const declaredBonds = new Map<string, number>(
    declared.bonds.map((delta) => [atomPairKey(delta.atomIds[0], delta.atomIds[1]), delta.electrons]),
  );
  const observedBonds = new Map<string, number>(
    observed.bonds.map((delta) => [atomPairKey(delta.atomIds[0], delta.atomIds[1]), delta.electrons]),
  );

  for (const key of new Set<string>([...declaredBonds.keys(), ...observedBonds.keys()])) {
    const declaredElectrons = declaredBonds.get(key) ?? 0;
    const observedElectrons = observedBonds.get(key) ?? 0;
    if (declaredElectrons !== observedElectrons) {
      mismatches.push({
        target: { kind: "atomPair", atomIds: parseAtomPairKey(key) },
        quantity: "bondingElectrons",
        declared: declaredElectrons,
        observed: observedElectrons,
      });
    }
  }

  return Object.freeze(mismatches);
}

src/edit.ts.source:
/**
 * Immutable structural edits.
 *
 * Every function here returns a new object and leaves its input untouched. That
 * is the rule CLAUDE.md states as "a step produces a new State rather than
 * mutating one", and it is the reason `from` and `to` on a step can be compared
 * at all: if a step mutated its input, the before picture would already be gone
 * by the time anything wanted to look at it.
 *
 * These are STRUCTURAL edits, not chemistry. `withBondOrder` will happily give
 * carbon five bonds. That is deliberate. An adversary has to be able to build a
 * broken fixture, and a constructor that refused would mean the valence check
 * could never be shown to fail on input that deserves it. Deciding what is legal
 * belongs to `packages/validators`.
 *
 * There is deliberately no `applyArrows`. See the note at the top of arrows.ts.
 *
 * The patch objects take `undefined` to mean "leave this alone". Fields are
 * copied one at a time rather than spread, because the tsconfig here turns on
 * `exactOptionalPropertyTypes` and a spread of a partial would quietly write
 * `undefined` into a field that is meant to be absent.
 */

import type { Atom, AtomStereo } from "./atom.js";
import type { Bond, BondOrder, BondStereo } from "./bond.js";
import type { AtomId, BondId, Point3, SpeciesId } from "./ids.js";
import type { Species } from "./species.js";
import { requireAtom, requireBond } from "./species.js";
import type { MechanismState, SpectatorDeclaration, StateMember } from "./state.js";

export interface AtomPatch {
  readonly formalCharge?: number;
  readonly lonePairs?: number;
  readonly unpairedElectrons?: number;
  readonly implicitHydrogens?: number;
  readonly isotope?: number;
  readonly stereo?: AtomStereo;
  readonly geometry?: Point3;
}

/**
 * Fields that can be cleared rather than changed.
 *
 * Removing stereochemistry is a real operation: an SN1 ionisation destroys the
 * stereocenter. There is no way to express "set this to absent" with a patch
 * whose absent field already means "leave alone", so clearing gets its own list.
 */
export type ClearableAtomField = "isotope" | "stereo" | "geometry";

function patchAtom(atom: Atom, patch: AtomPatch, clear: readonly ClearableAtomField[]): Atom {
  const clears = new Set<ClearableAtomField>(clear);

  const isotope = clears.has("isotope") ? undefined : (patch.isotope ?? atom.isotope);
  const stereo = clears.has("stereo") ? undefined : (patch.stereo ?? atom.stereo);
  const geometry = clears.has("geometry") ? undefined : (patch.geometry ?? atom.geometry);

  return Object.freeze({
    id: atom.id,
    element: atom.element,
    formalCharge: patch.formalCharge ?? atom.formalCharge,
    lonePairs: patch.lonePairs ?? atom.lonePairs,
    unpairedElectrons: patch.unpairedElectrons ?? atom.unpairedElectrons,
    implicitHydrogens: patch.implicitHydrogens ?? atom.implicitHydrogens,
    ...(isotope === undefined ? {} : { isotope }),
    ...(stereo === undefined ? {} : { stereo }),
    ...(geometry === undefined ? {} : { geometry }),
  });
}

function rebuildSpecies(
  species: Species,
  atoms: readonly Atom[],
  bonds: readonly Bond[],
): Species {
  return Object.freeze({
    id: species.id,
    atoms: Object.freeze([...atoms]),
    bonds: Object.freeze([...bonds]),
    ...(species.label === undefined ? {} : { label: species.label }),
    ...(species.declaredTorsions === undefined
      ? {}
      : { declaredTorsions: species.declaredTorsions }),
  });
}

export function withAtomPatch(
  species: Species,
  atomId: AtomId,
  patch: AtomPatch,
  clear: readonly ClearableAtomField[] = [],
): Species {
  const target = requireAtom(species, atomId);
  const patched = patchAtom(target, patch, clear);
  const atoms = species.atoms.map((atom) => (atom.id === atomId ? patched : atom));
  return rebuildSpecies(species, atoms, species.bonds);
}

export function withAddedAtom(species: Species, atom: Atom): Species {
  if (species.atoms.some((existing) => existing.id === atom.id)) {
    throw new Error(`Species ${species.id} already has an atom ${atom.id}`);
  }
  return rebuildSpecies(species, [...species.atoms, atom], species.bonds);
}

/** Removes the atom and every bond touching it. */
export function withoutAtom(species: Species, atomId: AtomId): Species {
  const atoms = species.atoms.filter((atom) => atom.id !== atomId);
  const bonds = species.bonds.filter((bond) => bond.a !== atomId && bond.b !== atomId);
  return rebuildSpecies(species, atoms, bonds);
}

export function withAddedBond(species: Species, bond: Bond): Species {
  if (species.bonds.some((existing) => existing.id === bond.id)) {
    throw new Error(`Species ${species.id} already has a bond ${bond.id}`);
  }
  return rebuildSpecies(species, species.atoms, [...species.bonds, bond]);
}

export function withoutBond(species: Species, bondId: BondId): Species {
  const bonds = species.bonds.filter((bond) => bond.id !== bondId);
  return rebuildSpecies(species, species.atoms, bonds);
}

export function withBondOrder(species: Species, bondId: BondId, order: BondOrder): Species {
  const target = requireBond(species, bondId);
  const updated: Bond = Object.freeze({
    id: target.id,
    a: target.a,
    b: target.b,
    order,
    ...(target.stereo === undefined ? {} : { stereo: target.stereo }),
  });
  const bonds = species.bonds.map((bond) => (bond.id === bondId ? updated : bond));
  return rebuildSpecies(species, species.atoms, bonds);
}

export function withBondStereo(
  species: Species,
  bondId: BondId,
  stereo: BondStereo | undefined,
): Species {
  const target = requireBond(species, bondId);
  const updated: Bond = Object.freeze({
    id: target.id,
    a: target.a,
    b: target.b,
    order: target.order,
    ...(stereo === undefined ? {} : { stereo }),
  });
  const bonds = species.bonds.map((bond) => (bond.id === bondId ? updated : bond));
  return rebuildSpecies(species, species.atoms, bonds);
}

function rebuildState(
  state: MechanismState,
  members: readonly StateMember[],
  spectators: readonly SpectatorDeclaration[],
): MechanismState {
  return Object.freeze({
    id: state.id,
    members: Object.freeze([...members]),
    spectators: Object.freeze([...spectators]),
  });
}

/** A new state with the same id and one member added. */
export function withMember(state: MechanismState, member: StateMember): MechanismState {
  if (state.members.some((existing) => existing.species.id === member.species.id)) {
    throw new Error(`State ${state.id} already has a species ${member.species.id}`);
  }
  return rebuildState(state, [...state.members, member], state.spectators);
}

export function withoutMember(state: MechanismState, speciesId: SpeciesId): MechanismState {
  const members = state.members.filter((member) => member.species.id !== speciesId);
  const spectators = state.spectators.filter(
    (declaration) => declaration.speciesId !== speciesId,
  );
  return rebuildState(state, members, spectators);
}

/** Replace one species in place, keeping its role. */
export function withReplacedSpecies(state: MechanismState, species: Species): MechanismState {
  if (!state.members.some((member) => member.species.id === species.id)) {
    throw new Error(`State ${state.id} has no species ${species.id} to replace`);
  }
  const members = state.members.map((member) =>
    member.species.id === species.id ? { species, role: member.role } : member,
  );
  return rebuildState(state, members, state.spectators);
}

/**
 * Record a spectator declaration.
 *
 * A separate, named function rather than a field somebody sets, because
 * CLAUDE.md requires declaring a spectator to be an explicit act. This is the
 * act. It refuses to declare a species that is not present, so the record cannot
 * quietly refer to nothing.
 */
export function declareSpectator(
  state: MechanismState,
  declaration: SpectatorDeclaration,
): MechanismState {
  if (!state.members.some((member) => member.species.id === declaration.speciesId)) {
    throw new Error(
      `Cannot declare species ${declaration.speciesId} a spectator: it is not in state ${state.id}`,
    );
  }
  if (state.spectators.some((existing) => existing.speciesId === declaration.speciesId)) {
    throw new Error(`Species ${declaration.speciesId} is already a spectator in state ${state.id}`);
  }
  return rebuildState(state, state.members, [...state.spectators, Object.freeze(declaration)]);
}

/** Withdraw a spectator declaration. Also an explicit act, and also recorded. */
export function withdrawSpectator(
  state: MechanismState,
  speciesId: SpeciesId,
): MechanismState {
  const spectators = state.spectators.filter(
    (declaration) => declaration.speciesId !== speciesId,
  );
  return rebuildState(state, state.members, spectators);
}

/**
 * A copy of a state under a new id.
 *
 * The usual way to start building the `to` state of a step: copy the `from`
 * state, then edit the copy. Species objects are shared by reference, which is
 * safe because every species in this package is frozen and every edit returns a
 * new one.
 */
export function copyStateAs(state: MechanismState, newId: string): MechanismState {
  return Object.freeze({
    id: newId,
    members: state.members,
    spectators: state.spectators,
  });
}

src/ids.ts.source:
/**
 * Identifiers, and the one invariant the whole engine rests on.
 *
 * These are plain string aliases rather than branded types. A brand would stop
 * you passing a BondId where an AtomId belongs, and it would also mean every
 * fixture file has to call a constructor to make a literal. The aliases are here
 * for the reader, not for the compiler. If mixed-up ids turn out to be a real
 * source of bugs later, brand them then, with the bug as the evidence.
 *
 * THE INVARIANT: atom ids are stable across a mechanism step.
 *
 * If an atom exists in the `from` state and in the `to` state, it carries the
 * same AtomId in both. That is what makes it possible to say "this carbon lost a
 * lone pair" rather than "some carbon somewhere lost a lone pair". Mass
 * conservation, stereochemistry tracking, and every arrow check depend on it.
 * Bond ids are NOT stable, because a bond that breaks and a bond that forms are
 * different bonds; bonds are matched across a step by their endpoint atom ids.
 *
 * No `react`, no DOM, no rendering, no RDKit anywhere in this package. Pure data
 * and numbers, per the contract in CLAUDE.md and the precedent set by
 * `berryBehaviour.ts` in the sibling repository.
 */

export type AtomId = string;
export type BondId = string;
export type SpeciesId = string;
export type StateId = string;
export type StepId = string;
export type ArrowId = string;
export type PathwayId = string;
export type AttemptId = string;

/**
 * Ids beginning with this prefix are reserved by the engine and must never be
 * used for a real atom, bond, or species.
 */
export const RESERVED_ID_PREFIX = "@";

/**
 * Stands in for an implicit hydrogen in a stereo neighbour list.
 *
 * A stereocenter usually has one hydrogen that is not drawn. The neighbour list
 * still needs four entries or the parity means nothing, so the undrawn hydrogen
 * gets this placeholder.
 */
export const IMPLICIT_HYDROGEN: AtomId = "@implicitH";

/**
 * Stands in for a lone pair in a stereo neighbour list.
 *
 * Needed for pyramidal centres that are stereogenic because of a lone pair
 * rather than a fourth substituent, such as a sulfoxide sulfur.
 */
export const LONE_PAIR: AtomId = "@lonePair";

/**
 * A neighbour slot in a stereo descriptor. Either a real atom id, or one of the
 * two sentinels above.
 *
 * This is a string alias like the rest, so the compiler will not catch a typo in
 * a sentinel. `isSentinelId` exists so a validator can catch it at runtime.
 */
export type StereoNeighbor = AtomId;

export function isSentinelId(id: string): boolean {
  return id.startsWith(RESERVED_ID_PREFIX);
}

export function isImplicitHydrogenSlot(id: StereoNeighbor): boolean {
  return id === IMPLICIT_HYDROGEN;
}

export function isLonePairSlot(id: StereoNeighbor): boolean {
  return id === LONE_PAIR;
}

/**
 * A point in molecular space, in angstroms.
 *
 * This is chemistry geometry, not screen layout. Nothing in this package knows
 * about pixels. Renderers compute their own coordinates; conformational
 * questions such as an E2 dihedral read these.
 */
export interface Point3 {
  readonly x: number;
  readonly y: number;
  readonly z: number;
}

src/resolution.ts.source:
/**
 * AXIS TWO: what a student's attempt resolved to.
 *
 * Read the two axis note at the top of step.ts first. Axis one is what a step
 * IS and lives on the step. Axis two is this file, and it is the outcome of a
 * grading act: it is about one student at one moment, it did not exist before
 * the attempt, and the next attempt replaces it.
 *
 * `AttemptResolution` is a discriminated union. That is a normal TypeScript
 * pattern rather than an exotic one: several object shapes share one literal
 * field, here `kind`, and the compiler narrows to the right shape once you check
 * it. The reason for using it rather than one interface with optional fields is
 * that CLAUDE.md requires case two to carry the name of the route taken and case
 * three to carry the name of what was actually built. With optional fields those
 * are promises in a comment. As a union they are compile errors when missing.
 *
 * Every one of the four carries a `cause`. Including `correct`. A student who
 * gets it right is told which route they were recognised as taking, which is
 * worth as much as the mark.
 */

import type { NamedCause, ResolutionKind } from "./causes.js";
import { causeAppliesTo, causeDefinition } from "./causes.js";
import type { AttemptId, SpeciesId, StepId } from "./ids.js";
import type { MechanismRoute, TransformationKind } from "./routes.js";
import type { MechanismStep } from "./step.js";

export type { ResolutionKind } from "./causes.js";

/**
 * What a student actually built, named.
 *
 * Structured rather than a sentence, so `valid_not_requested` can say "you built
 * an elimination" and a later phase can count how often that happens without
 * parsing English.
 */
export interface TransformationDescriptor {
  readonly kind: TransformationKind;
  readonly route?: MechanismRoute;
  /** The species that make up what they produced. */
  readonly productSpeciesIds: readonly SpeciesId[];
}

/**
 * The four outcomes.
 *
 * `advisories` is the graded chemistry half. A neopentyl SN2 resolves to
 * `correct` with `sn2_center_strongly_hindered` in advisories and the competing
 * pathway named on that cause, which is what CLAUDE.md asks for: say it is
 * strongly disfavoured and name what wins instead, rather than rejecting it and
 * deleting the lesson.
 */
export type AttemptResolution =
  | {
      readonly kind: "correct";
      readonly route: MechanismRoute;
      readonly cause: NamedCause;
      readonly advisories: readonly NamedCause[];
    }
  | {
      readonly kind: "correct_alternative_route";
      /** The route the student took. Required, per CLAUDE.md result type two. */
      readonly routeTaken: MechanismRoute;
      readonly routeRequested: MechanismRoute;
      readonly cause: NamedCause;
      readonly advisories: readonly NamedCause[];
    }
  | {
      readonly kind: "valid_not_requested";
      /** What they actually built. Required, per CLAUDE.md result type three. */
      readonly built: TransformationDescriptor;
      readonly cause: NamedCause;
      readonly advisories: readonly NamedCause[];
    }
  | {
      readonly kind: "invalid";
      /** The specific rule violated. Required, per CLAUDE.md result type four. */
      readonly cause: NamedCause;
      readonly advisories: readonly NamedCause[];
    };

/**
 * The two axes composed: one attempt is a step the student built plus the
 * resolution grading it produced.
 *
 * `built.identity` is axis one for what they drew. `resolution` is axis two.
 * Neither is derivable from the other, which is the point.
 */
export interface StudentAttempt {
  readonly id: AttemptId;
  readonly built: MechanismStep;
  /** The step the problem asked for, when there is a single intended answer. */
  readonly expectedStepId?: StepId;
  readonly resolution: AttemptResolution;
}

/** Whether this resolution counts as chemically sound, regardless of the mark. */
export function isChemicallyValid(resolution: AttemptResolution): boolean {
  return resolution.kind !== "invalid";
}

/** Whether this resolution reaches the requested product. */
export function reachesRequestedProduct(resolution: AttemptResolution): boolean {
  return resolution.kind === "correct" || resolution.kind === "correct_alternative_route";
}

/** Every named cause on a resolution, primary first, then advisories. */
export function resolutionCauses(resolution: AttemptResolution): readonly NamedCause[] {
  return [resolution.cause, ...resolution.advisories];
}

/**
 * Whether the primary cause is one the registry allows on this outcome.
 *
 * This is a consistency question about the model, not a chemistry check. It
 * catches a resolution built with a blocking cause on a correct answer, which
 * would tell a student they were right and then explain why they were wrong.
 */
export function primaryCauseIsConsistent(resolution: AttemptResolution): boolean {
  return causeAppliesTo(resolution.cause.id, resolution.kind);
}

/**
 * Advisories that are blocking causes, which they should never be.
 *
 * A blocking cause means the chemistry is impossible, and impossible chemistry
 * is not advice.
 */
export function blockingAdvisories(resolution: AttemptResolution): readonly NamedCause[] {
  return resolution.advisories.filter(
    (cause) => causeDefinition(cause.id).severity === "blocking",
  );
}

/** How many distinct cause ids appear across a set of resolutions. */
export function distinctCauseCount(resolutions: readonly AttemptResolution[]): number {
  const ids = new Set<string>();
  for (const resolution of resolutions) {
    for (const cause of resolutionCauses(resolution)) {
      ids.add(cause.id);
    }
  }
  return ids.size;
}

/** Count of resolutions by outcome. The shape a feedback report is built from. */
export function countByKind(
  resolutions: readonly AttemptResolution[],
): Readonly<Record<ResolutionKind, number>> {
  const counts: Record<ResolutionKind, number> = {
    correct: 0,
    correct_alternative_route: 0,
    valid_not_requested: 0,
    invalid: 0,
  };
  for (const resolution of resolutions) {
    counts[resolution.kind] += 1;
  }
  return counts;
}

src/species.ts.source:
/**
 * A Species is one connected molecule or ion.
 *
 * Connectivity is a rule about a Species, not a thing this file enforces at
 * construction time. `connectedComponentCount` is provided so a validator can
 * assert it and so an adversary can build a fixture that violates it. A
 * constructor that threw would make that fixture unbuildable, which would mean
 * the check could never be shown to fail on broken input, which is the one thing
 * VERIFICATION.md calls the highest leverage instruction in the whole set.
 */

import type { Atom } from "./atom.js";
import type { Bond } from "./bond.js";
import { bondTouches, otherEnd } from "./bond.js";
import type { AtomId, BondId, SpeciesId } from "./ids.js";

/**
 * A torsion angle the author asserts, in degrees.
 *
 * E2 needs a dihedral. Rather than requiring full 3D coordinates on every atom
 * of every problem, an author can state the one torsion the mechanism turns on
 * and say why. `justification` is required because a stated torsion that nobody
 * defended is a number a validator will trust and a student will be graded
 * against.
 *
 * Zero degrees is syn periplanar, 180 is anti periplanar.
 */
export interface DeclaredTorsion {
  readonly atoms: readonly [AtomId, AtomId, AtomId, AtomId];
  readonly degrees: number;
  readonly justification: string;
}

export interface Species {
  readonly id: SpeciesId;
  /** Human readable name for debugging and for feedback text. Not an identity. */
  readonly label?: string;
  readonly atoms: readonly Atom[];
  readonly bonds: readonly Bond[];
  readonly declaredTorsions?: readonly DeclaredTorsion[];
}

export interface SpeciesInput {
  readonly id: SpeciesId;
  readonly label?: string;
  readonly atoms: readonly Atom[];
  readonly bonds?: readonly Bond[];
  readonly declaredTorsions?: readonly DeclaredTorsion[];
}

export function createSpecies(input: SpeciesInput): Species {
  return Object.freeze({
    id: input.id,
    atoms: Object.freeze([...input.atoms]),
    bonds: Object.freeze([...(input.bonds ?? [])]),
    ...(input.label === undefined ? {} : { label: input.label }),
    ...(input.declaredTorsions === undefined
      ? {}
      : { declaredTorsions: Object.freeze([...input.declaredTorsions]) }),
  });
}

export function findAtom(species: Species, atomId: AtomId): Atom | undefined {
  return species.atoms.find((atom) => atom.id === atomId);
}

/** Same as `findAtom`, but throws. For call sites that have already checked. */
export function requireAtom(species: Species, atomId: AtomId): Atom {
  const atom = findAtom(species, atomId);
  if (atom === undefined) {
    throw new Error(`Species ${species.id} has no atom ${atomId}`);
  }
  return atom;
}

export function findBond(species: Species, bondId: BondId): Bond | undefined {
  return species.bonds.find((bond) => bond.id === bondId);
}

export function requireBond(species: Species, bondId: BondId): Bond {
  const bond = findBond(species, bondId);
  if (bond === undefined) {
    throw new Error(`Species ${species.id} has no bond ${bondId}`);
  }
  return bond;
}

/** The bond joining two atoms, if there is one. */
export function findBondBetween(species: Species, a: AtomId, b: AtomId): Bond | undefined {
  return species.bonds.find(
    (bond) => (bond.a === a && bond.b === b) || (bond.a === b && bond.b === a),
  );
}

export function bondsAt(species: Species, atomId: AtomId): readonly Bond[] {
  return species.bonds.filter((bond) => bondTouches(bond, atomId));
}

/** Neighbour atom ids. Implicit hydrogens are not in here; they have no id. */
export function neighborIds(species: Species, atomId: AtomId): readonly AtomId[] {
  return bondsAt(species, atomId).map((bond) => otherEnd(bond, atomId));
}

/**
 * Bonds naming an atom this Species does not contain.
 *
 * Should always be empty. A dangling bond makes every downstream count wrong in
 * a way that reads as a chemistry error rather than a data error, so it is worth
 * being able to report it by name.
 */
export function danglingBondIds(species: Species): readonly BondId[] {
  const known = new Set<AtomId>(species.atoms.map((atom) => atom.id));
  return species.bonds
    .filter((bond) => !known.has(bond.a) || !known.has(bond.b))
    .map((bond) => bond.id);
}

/**
 * How many disconnected fragments this Species contains.
 *
 * One is the only correct answer for a well formed Species. Zero means it has no
 * atoms. Anything above one means two molecules were packed into one Species,
 * which breaks the multiset accounting in state.ts because they can no longer be
 * given separate roles or declared spectators separately.
 */
export function connectedComponentCount(species: Species): number {
  if (species.atoms.length === 0) return 0;

  const adjacency = new Map<AtomId, AtomId[]>();
  for (const atom of species.atoms) {
    adjacency.set(atom.id, []);
  }
  for (const bond of species.bonds) {
    adjacency.get(bond.a)?.push(bond.b);
    adjacency.get(bond.b)?.push(bond.a);
  }

  const seen = new Set<AtomId>();
  let components = 0;

  for (const atom of species.atoms) {
    if (seen.has(atom.id)) continue;
    components += 1;
    const stack: AtomId[] = [atom.id];
    while (stack.length > 0) {
      const current = stack.pop();
      if (current === undefined || seen.has(current)) continue;
      seen.add(current);
      for (const next of adjacency.get(current) ?? []) {
        if (!seen.has(next)) stack.push(next);
      }
    }
  }

  return components;
}

src/state.ts.source:
/**
 * A State is a multiset of Species. This is the system boundary rule.
 *
 * CLAUDE.md and VERIFICATION.md B5 both say why, and it is worth repeating at
 * the type that implements it: conservation is asserted over the multiset, not
 * over the substrate. Protonation and deprotonation are the two most common
 * steps in the corpus and neither conserves charge on the substrate alone. A
 * model that tracks one molecule reports a charge violation on every correct
 * protonation, and the suite is red from the first fixture for a modelling
 * reason rather than an implementation one.
 *
 * MULTIPLICITY IS REPETITION, NOT A COUNT FIELD.
 *
 * Two equivalents of methanol are two members with two different SpeciesIds, not
 * one member with `count: 2`. That costs a little memory and buys the thing the
 * whole engine needs: when one of the two reacts, an arrow can name the atom it
 * reacted at. A count field makes the two indistinguishable, and an arrow into
 * "one of the two methanols" cannot be checked against a bond delta.
 *
 * ROLE LIVES ON THE MEMBERSHIP, NOT ON THE SPECIES.
 *
 * "Substrate" is a job a molecule holds in one reaction. Water is the solvent in
 * one problem and the nucleophile in the next. Putting `role` on Species would
 * make the same molecule two different objects for no chemical reason.
 */

import type { Species } from "./species.js";
import { findAtom, findBond, findBondBetween } from "./species.js";
import type { Atom } from "./atom.js";
import type { Bond } from "./bond.js";
import type { AtomId, BondId, SpeciesId, StateId } from "./ids.js";

export type SpeciesRole =
  | "substrate"
  | "reagent"
  | "nucleophile"
  | "electrophile"
  | "acid"
  | "base"
  | "catalyst"
  | "counterion"
  | "solvent"
  | "intermediate"
  | "leaving_group"
  | "product"
  | "byproduct";

export interface StateMember {
  readonly species: Species;
  readonly role: SpeciesRole;
}

/**
 * Why a species is excluded from conservation.
 *
 * A named enum rather than prose, so a validator can group by it, a report can
 * count it, and an adversary can go looking for the reason that gets abused. The
 * prose lives alongside in `justification`, which is for the human reading the
 * failure, not for the machine.
 */
export type SpectatorReason =
  | "inert_solvent"
  | "unreacting_counterion"
  | "bulk_medium"
  | "authored_simplification";

/**
 * An explicit, recorded act of excluding a species from conservation.
 *
 * Not a boolean on Species, and not implicit in a role. CLAUDE.md requires that
 * declaring a spectator be something a validator can see and an adversary can
 * attack, and a flag buried in a molecule is neither: it does not say who
 * decided, or why, and it travels with the molecule into problems where it is
 * not true.
 *
 * The invariant a validator must enforce, which is the reason this is safe at
 * all: a declared spectator must be structurally identical in both states of any
 * step it is declared across. A spectator that changes is not a spectator, and
 * `spectator_changed_during_step` is the named cause for it.
 */
export interface SpectatorDeclaration {
  readonly speciesId: SpeciesId;
  readonly reason: SpectatorReason;
  /** Why this is genuinely a spectator here. Required. Read by humans. */
  readonly justification: string;
  /** Who made the call. A problem id, an author, or a tool name. */
  readonly declaredBy: string;
}

export interface MechanismState {
  readonly id: StateId;
  readonly members: readonly StateMember[];
  readonly spectators: readonly SpectatorDeclaration[];
}

export interface MechanismStateInput {
  readonly id: StateId;
  readonly members: readonly StateMember[];
  readonly spectators?: readonly SpectatorDeclaration[];
}

export function createState(input: MechanismStateInput): MechanismState {
  return Object.freeze({
    id: input.id,
    members: Object.freeze([...input.members]),
    spectators: Object.freeze([...(input.spectators ?? [])]),
  });
}

export function isSpectator(state: MechanismState, speciesId: SpeciesId): boolean {
  return state.spectators.some((declaration) => declaration.speciesId === speciesId);
}

export function spectatorDeclarationFor(
  state: MechanismState,
  speciesId: SpeciesId,
): SpectatorDeclaration | undefined {
  return state.spectators.find((declaration) => declaration.speciesId === speciesId);
}

/** Members that conservation is asserted over. Spectators are excluded. */
export function participatingMembers(state: MechanismState): readonly StateMember[] {
  return state.members.filter((member) => !isSpectator(state, member.species.id));
}

export function spectatorMembers(state: MechanismState): readonly StateMember[] {
  return state.members.filter((member) => isSpectator(state, member.species.id));
}

/**
 * Spectator declarations naming a species that is not in the state.
 *
 * Should always be empty. A declaration pointing at nothing is either a typo or
 * an attempt to pre-authorise excluding something that gets added later, and
 * both are worth naming.
 */
export function orphanSpectatorDeclarations(
  state: MechanismState,
): readonly SpectatorDeclaration[] {
  const present = new Set<SpeciesId>(state.members.map((member) => member.species.id));
  return state.spectators.filter((declaration) => !present.has(declaration.speciesId));
}

export function findSpecies(state: MechanismState, speciesId: SpeciesId): Species | undefined {
  return state.members.find((member) => member.species.id === speciesId)?.species;
}

export function findMember(state: MechanismState, speciesId: SpeciesId): StateMember | undefined {
  return state.members.find((member) => member.species.id === speciesId);
}

export interface AtomLocation {
  readonly species: Species;
  readonly atom: Atom;
}

/**
 * Locate an atom anywhere in the state.
 *
 * Atom ids are unique across the whole state, not just within a species. That is
 * what lets an arrow name a source in one molecule and a sink in another without
 * carrying a species id on every endpoint.
 */
export function findAtomInState(state: MechanismState, atomId: AtomId): AtomLocation | undefined {
  for (const member of state.members) {
    const atom = findAtom(member.species, atomId);
    if (atom !== undefined) {
      return { species: member.species, atom };
    }
  }
  return undefined;
}

/**
 * Atom ids that appear in more than one species in this state.
 *
 * Should always be empty. A duplicate id makes `findAtomInState` return whichever
 * molecule happens to be first in the list, which is a bug that shows up as
 * chemistry going wrong in one molecule and not the other.
 */
export function duplicateAtomIds(state: MechanismState): readonly AtomId[] {
  const seen = new Set<AtomId>();
  const duplicates = new Set<AtomId>();
  for (const member of state.members) {
    for (const atom of member.species.atoms) {
      if (seen.has(atom.id)) {
        duplicates.add(atom.id);
      }
      seen.add(atom.id);
    }
  }
  return [...duplicates];
}

/**
 * Species ids used by more than one member of this state.
 *
 * Should always be empty, and the sentence it enforces is the one at the top of
 * this file: multiplicity is repetition with distinct ids, never one id written
 * twice. Nothing used to enforce it, and the consequences are worse than a
 * cosmetic duplicate.
 *
 * `findSpecies` and `findMember` both resolve to whichever member `Array.find`
 * reaches first, so the second copy is permanently invisible to every lookup,
 * including the structural identity comparison in the spectator check. Meanwhile
 * `conservedTotals` walks `members` directly, so the second copy is fully counted
 * in mass, charge, and electrons. One half of the engine can see it and the other
 * half cannot, which is the shape of a bug that reads as chemistry going wrong.
 *
 * Returned sorted so a failure report is stable between runs.
 */
export function duplicateSpeciesIds(state: MechanismState): readonly SpeciesId[] {
  const seen = new Set<SpeciesId>();
  const duplicates = new Set<SpeciesId>();
  for (const member of state.members) {
    if (seen.has(member.species.id)) {
      duplicates.add(member.species.id);
    }
    seen.add(member.species.id);
  }
  return [...duplicates].sort();
}

/** How many members of this state carry a given species id. Normally 0 or 1. */
export function speciesIdOccurrences(state: MechanismState, speciesId: SpeciesId): number {
  return state.members.filter((member) => member.species.id === speciesId).length;
}

export interface BondLocation {
  readonly species: Species;
  readonly bond: Bond;
}

/**
 * Locate a bond anywhere in the state, by id.
 *
 * Bond ids are only unique within a species by construction, so this returns the
 * first match. A state carrying the same bond id in two species is a data error
 * the valence check reports; this function does not silently arbitrate it.
 */
export function findBondInState(state: MechanismState, bondId: BondId): BondLocation | undefined {
  for (const member of state.members) {
    const bond = findBond(member.species, bondId);
    if (bond !== undefined) {
      return { species: member.species, bond };
    }
  }
  return undefined;
}

/**
 * Whether two atoms are joined by a bond anywhere in this state.
 *
 * Atoms in two different species are never bonded, which is what makes this the
 * right adjacency test for arrow legality: an arrow reaching from one molecule
 * into another has to form a bond, it cannot travel along one that is not there.
 */
export function atomsAreBonded(state: MechanismState, a: AtomId, b: AtomId): boolean {
  if (a === b) return false;
  for (const member of state.members) {
    if (findBondBetween(member.species, a, b) !== undefined) return true;
  }
  return false;
}

export function allAtoms(state: MechanismState): readonly Atom[] {
  return state.members.flatMap((member) => [...member.species.atoms]);
}

export function membersWithRole(
  state: MechanismState,
  role: SpeciesRole,
): readonly StateMember[] {
  return state.members.filter((member) => member.role === role);
}

