import { describe, expect, it } from "vitest";

import { allMechanismRoutes, routeLabel, type MechanismRoute } from "../src/routes.ts";

describe("the route registry", () => {
  it("is frozen and non empty", () => {
    expect(Object.isFrozen(allMechanismRoutes())).toBe(true);
    expect(allMechanismRoutes().length).toBeGreaterThan(0);
  });

  it("covers the four families the Phase 1 corpus spans", () => {
    // BUILD-PROMPT.md Phase 1 exit names substitution, elimination, addition, and
    // carbonyl chemistry. A route missing here cannot be named by
    // correct_alternative_route, so the corpus could not describe its own answer.
    for (const route of [
      "sn1",
      "sn2",
      "e1",
      "e2",
      "electrophilic_addition_alkene",
      "nucleophilic_addition_carbonyl",
      "nucleophilic_acyl_substitution",
    ] as const) {
      expect(allMechanismRoutes()).toContain(route);
    }
  });

  it("has no duplicates", () => {
    const routes = allMechanismRoutes();
    expect(new Set(routes).size).toBe(routes.length);
  });
});

describe("routeLabel", () => {
  it("gives every route a non empty human readable label", () => {
    const routes = allMechanismRoutes();
    expect(routes.length).toBeGreaterThan(0);
    for (const route of routes) {
      const label = routeLabel(route);
      expect(typeof label).toBe("string");
      expect(label.trim().length).toBeGreaterThan(0);
    }
  });

  it("gives every route a distinct label", () => {
    // Feedback names the competing pathway by label. Two routes sharing a label makes
    // "a different route wins here" unreadable.
    const labels = allMechanismRoutes().map((route) => routeLabel(route));
    expect(new Set(labels).size).toBe(labels.length);
  });

  it("uses the capitalisation a textbook uses", () => {
    // The union member is snake case for the machine; the label is what a student reads.
    // If these were the same string the feedback copy would say "sn2".
    expect(routeLabel("sn1")).toBe("SN1");
    expect(routeLabel("sn2")).toBe("SN2");
    expect(routeLabel("e2")).toBe("E2");
    expect(routeLabel("e1cb")).toBe("E1cb");
    expect(routeLabel("acid_base_proton_transfer")).toBe("acid base proton transfer");
  });

  it("returns undefined for a route that is not in the table rather than a wrong label", () => {
    expect(routeLabel("not_a_route" as MechanismRoute)).toBeUndefined();
  });
});

test/arrows.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  createArrow,
  fromBond,
  fromLonePair,
  fromSingleElectron,
  referencedAtomIds,
  referencedBondIds,
  toAtom,
  toBondBetween,
} from "../src/arrows.ts";

describe("source and sink constructors", () => {
  it("tag each shape with the kind the union discriminates on", () => {
    expect(fromLonePair("o1")).toEqual({ kind: "lonePair", atomId: "o1" });
    expect(fromBond("b1")).toEqual({ kind: "bond", bondId: "b1" });
    expect(fromSingleElectron("br1")).toEqual({ kind: "singleElectron", atomId: "br1" });
    expect(toAtom("cl1")).toEqual({ kind: "atom", atomId: "cl1" });
    expect(toBondBetween("o1", "c1")).toEqual({ kind: "betweenAtoms", atomIds: ["o1", "c1"] });
  });

  it("keeps the two atoms of a bond forming sink in the order written", () => {
    // The pair is unordered chemically, but silently reordering here would make an
    // arrow's stored form differ from what the author wrote and a diff unreadable.
    const sink = toBondBetween("o1", "c1");
    expect(sink.kind).toBe("betweenAtoms");
    if (sink.kind !== "betweenAtoms") throw new Error("sink kind narrowed wrong");
    expect(sink.atomIds).toEqual(["o1", "c1"]);
  });
});

describe("createArrow", () => {
  it("defaults to two electrons, the ordinary double barbed arrow", () => {
    const arrow = createArrow({ id: "a1", source: fromLonePair("o1"), sink: toAtom("c1") });
    expect(arrow.electrons).toBe(2);
  });

  it("takes one electron when a radical step says so explicitly", () => {
    const arrow = createArrow({
      id: "a1",
      source: fromSingleElectron("br1"),
      sink: toBondBetween("br1", "c1"),
      electrons: 1,
    });
    expect(arrow.electrons).toBe(1);
  });

  it("keeps its id, source, and sink", () => {
    const arrow = createArrow({ id: "a7", source: fromBond("b1"), sink: toAtom("cl1") });
    expect(arrow.id).toBe("a7");
    expect(arrow.source).toEqual({ kind: "bond", bondId: "b1" });
    expect(arrow.sink).toEqual({ kind: "atom", atomId: "cl1" });
  });

  it("freezes the arrow and both of its ends", () => {
    const arrow = createArrow({ id: "a1", source: fromLonePair("o1"), sink: toAtom("c1") });
    expect(Object.isFrozen(arrow)).toBe(true);
    expect(Object.isFrozen(arrow.source)).toBe(true);
    expect(Object.isFrozen(arrow.sink)).toBe(true);
  });

  it("copies the source and sink rather than aliasing the caller's objects", () => {
    const source = { kind: "lonePair", atomId: "o1" } as const;
    const arrow = createArrow({ id: "a1", source, sink: toAtom("c1") });
    expect(arrow.source).not.toBe(source);
    expect(arrow.source).toEqual(source);
  });
});

describe("referencedAtomIds", () => {
  it("names the source atom and the sink atom for a lone pair to atom arrow", () => {
    const arrow = createArrow({ id: "a1", source: fromLonePair("o1"), sink: toAtom("c1") });
    expect(referencedAtomIds(arrow)).toEqual(["o1", "c1"]);
  });

  it("names both ends of a bond forming sink", () => {
    const arrow = createArrow({
      id: "a1",
      source: fromLonePair("o1"),
      sink: toBondBetween("o1", "c1"),
    });
    expect(referencedAtomIds(arrow)).toEqual(["o1", "o1", "c1"]);
  });

  it("names the atom a single electron source sits on", () => {
    const arrow = createArrow({
      id: "a1",
      source: fromSingleElectron("br1"),
      sink: toAtom("c1"),
      electrons: 1,
    });
    expect(referencedAtomIds(arrow)).toContain("br1");
  });

  it("names no atom for a bond source, because resolving a bond id needs the species", () => {
    // Deliberate. legality.ts resolves a BondId against the state; this file has no
    // state, and inventing the two ends here would be a lookup with no table.
    const arrow = createArrow({ id: "a1", source: fromBond("b1"), sink: toAtom("cl1") });
    expect(referencedAtomIds(arrow)).toEqual(["cl1"]);
  });
});

describe("referencedBondIds", () => {
  it("names the bond a bond source reads from", () => {
    const arrow = createArrow({ id: "a1", source: fromBond("b1"), sink: toAtom("cl1") });
    expect(referencedBondIds(arrow)).toEqual(["b1"]);
  });

  it("is empty for a source that is not a bond", () => {
    expect(
      referencedBondIds(createArrow({ id: "a1", source: fromLonePair("o1"), sink: toAtom("c1") })),
    ).toEqual([]);
    expect(
      referencedBondIds(
        createArrow({
          id: "a1",
          source: fromSingleElectron("br1"),
          sink: toAtom("c1"),
          electrons: 1,
        }),
      ),
    ).toEqual([]);
  });
});

test/resolution.test.ts.source:
import { describe, expect, it } from "vitest";

import { namedCause } from "../src/causes.ts";
import {
  blockingAdvisories,
  countByKind,
  distinctCauseCount,
  isChemicallyValid,
  primaryCauseIsConsistent,
  reachesRequestedProduct,
  resolutionCauses,
  type AttemptResolution,
} from "../src/resolution.ts";

const correct: AttemptResolution = {
  kind: "correct",
  route: "sn2",
  cause: namedCause({ id: "matches_requested_route" }),
  advisories: [],
};

const alternative: AttemptResolution = {
  kind: "correct_alternative_route",
  routeTaken: "sn1",
  routeRequested: "sn2",
  cause: namedCause({ id: "alternative_route_same_product" }),
  advisories: [],
};

const notRequested: AttemptResolution = {
  kind: "valid_not_requested",
  built: { kind: "elimination", route: "e2", productSpeciesIds: ["sp-alkene"] },
  cause: namedCause({ id: "valid_transformation_not_requested" }),
  advisories: [],
};

const invalid: AttemptResolution = {
  kind: "invalid",
  cause: namedCause({ id: "arrow_endpoints_not_adjacent", subjects: [{ kind: "arrow", arrowId: "a1" }] }),
  advisories: [],
};

const all = [correct, alternative, notRequested, invalid] as const;

describe("the four result types", () => {
  it("carries the route taken on an alternative route, per CLAUDE.md result type two", () => {
    // Students reach right answers by legitimate other paths, and grading that as "not
    // the requested transformation" is unfair and generates support mail.
    expect(alternative.routeTaken).toBe("sn1");
    expect(alternative.routeRequested).toBe("sn2");
  });

  it("carries what was actually built on valid_not_requested, per result type three", () => {
    expect(notRequested.built.kind).toBe("elimination");
    expect(notRequested.built.route).toBe("e2");
    expect(notRequested.built.productSpeciesIds).toEqual(["sp-alkene"]);
  });

  it("gives every outcome a named cause, including the correct one", () => {
    // A student who gets it right is told which route they were recognised as taking,
    // which is worth as much as the mark.
    for (const resolution of all) {
      expect(resolution.cause.id.length).toBeGreaterThan(0);
    }
  });
});

describe("isChemicallyValid", () => {
  it("is true for the three sound outcomes and false only for invalid", () => {
    expect(isChemicallyValid(correct)).toBe(true);
    expect(isChemicallyValid(alternative)).toBe(true);
    expect(isChemicallyValid(notRequested)).toBe(true);
    expect(isChemicallyValid(invalid)).toBe(false);
  });
});

describe("reachesRequestedProduct", () => {
  it("is true for both correct outcomes", () => {
    expect(reachesRequestedProduct(correct)).toBe(true);
    expect(reachesRequestedProduct(alternative)).toBe(true);
  });

  it("is false for a sound but different transformation", () => {
    // Sound chemistry that does not reach the requested product. Separating this from
    // isChemicallyValid is the whole reason there are four outcomes and not two.
    expect(reachesRequestedProduct(notRequested)).toBe(false);
    expect(reachesRequestedProduct(invalid)).toBe(false);
  });
});

describe("resolutionCauses", () => {
  it("puts the primary cause first, then the advisories in order", () => {
    const graded: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [
        namedCause({ id: "sn2_center_strongly_hindered", relatedRoute: "carbocation_rearrangement" }),
        namedCause({ id: "leaving_group_too_poor" }),
      ],
    };
    expect(resolutionCauses(graded).map((cause) => cause.id)).toEqual([
      "matches_requested_route",
      "sn2_center_strongly_hindered",
      "leaving_group_too_poor",
    ]);
  });

  it("is just the primary cause when there are no advisories", () => {
    expect(resolutionCauses(invalid).map((cause) => cause.id)).toEqual([
      "arrow_endpoints_not_adjacent",
    ]);
  });
});

describe("primaryCauseIsConsistent", () => {
  it("accepts each outcome's own success cause", () => {
    expect(primaryCauseIsConsistent(correct)).toBe(true);
    expect(primaryCauseIsConsistent(alternative)).toBe(true);
    expect(primaryCauseIsConsistent(notRequested)).toBe(true);
    expect(primaryCauseIsConsistent(invalid)).toBe(true);
  });

  it("rejects a blocking cause on a correct answer", () => {
    // Which would tell a student they were right and then explain why they were wrong.
    const contradictory: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "valence_exceeded" }),
      advisories: [],
    };
    expect(primaryCauseIsConsistent(contradictory)).toBe(false);
  });

  it("rejects a success cause on an invalid attempt", () => {
    const contradictory: AttemptResolution = {
      kind: "invalid",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [],
    };
    expect(primaryCauseIsConsistent(contradictory)).toBe(false);
  });

  it("rejects one outcome's success cause used on another outcome", () => {
    const swapped: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "alternative_route_same_product" }),
      advisories: [],
    };
    expect(primaryCauseIsConsistent(swapped)).toBe(false);
  });

  it("accepts an advisory cause as the primary cause where the registry allows it", () => {
    const advisoryPrimary: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "sn2_center_strongly_hindered" }),
      advisories: [],
    };
    expect(primaryCauseIsConsistent(advisoryPrimary)).toBe(true);
  });
});

describe("blockingAdvisories", () => {
  it("is empty when every advisory is advisory", () => {
    const graded: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [namedCause({ id: "sn2_center_strongly_hindered" })],
    };
    expect(blockingAdvisories(graded)).toEqual([]);
  });

  it("names an advisory that is really a blocking cause", () => {
    // Impossible chemistry is not advice.
    const smuggled: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [
        namedCause({ id: "sn2_center_strongly_hindered" }),
        namedCause({ id: "valence_exceeded" }),
      ],
    };
    expect(blockingAdvisories(smuggled).map((cause) => cause.id)).toEqual(["valence_exceeded"]);
  });

  it("ignores the primary cause, however blocking it is", () => {
    expect(blockingAdvisories(invalid)).toEqual([]);
  });

  it("does not treat an informational cause as blocking", () => {
    const informational: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [namedCause({ id: "matches_requested_route" })],
    };
    expect(blockingAdvisories(informational)).toEqual([]);
  });
});

describe("distinctCauseCount", () => {
  it("is zero over an empty list", () => {
    expect(distinctCauseCount([])).toBe(0);
  });

  it("counts a cause once however many resolutions carry it", () => {
    expect(distinctCauseCount([invalid, invalid, invalid])).toBe(1);
  });

  it("counts advisories as well as primary causes", () => {
    // The feedback axis measures distinct named causes reachable. An advisory that only
    // ever rides along is still a distinct thing a student was told.
    const graded: AttemptResolution = {
      kind: "correct",
      route: "sn2",
      cause: namedCause({ id: "matches_requested_route" }),
      advisories: [namedCause({ id: "sn2_center_strongly_hindered" })],
    };
    expect(distinctCauseCount([graded])).toBe(2);
  });

  it("counts across resolutions", () => {
    expect(distinctCauseCount([...all])).toBe(4);
  });
});

describe("countByKind", () => {
  it("reports zero for every kind over an empty list rather than omitting keys", () => {
    expect(countByKind([])).toEqual({
      correct: 0,
      correct_alternative_route: 0,
      valid_not_requested: 0,
      invalid: 0,
    });
  });

  it("counts one of each", () => {
    expect(countByKind([...all])).toEqual({
      correct: 1,
      correct_alternative_route: 1,
      valid_not_requested: 1,
      invalid: 1,
    });
  });

  it("accumulates repeats", () => {
    expect(countByKind([invalid, invalid, correct])).toEqual({
      correct: 1,
      correct_alternative_route: 0,
      valid_not_requested: 0,
      invalid: 2,
    });
  });

  it("sums to the number of resolutions given", () => {
    const counts = countByKind([...all, invalid]);
    expect(Object.values(counts).reduce((a, b) => a + b, 0)).toBe(5);
  });
});

test/species.test.ts.source:
import { describe, expect, it } from "vitest";

import { createSpecies } from "../src/species.ts";
import {
  bondsAt,
  connectedComponentCount,
  danglingBondIds,
  findAtom,
  findBond,
  findBondBetween,
  neighborIds,
  requireAtom,
  requireBond,
} from "../src/species.ts";
import { atom, bond, chloromethane, species } from "./helpers.ts";

const ethanol = () => species(
  "sp-ethanol",
  [
    atom("c1", "C", { implicitHydrogens: 3 }),
    atom("c2", "C", { implicitHydrogens: 2 }),
    atom("o1", "O", { lonePairs: 2, implicitHydrogens: 1 }),
  ],
  [bond("b1", "c1", "c2"), bond("b2", "c2", "o1")],
);

describe("createSpecies", () => {
  it("defaults bonds to an empty list, because a lone ion has none", () => {
    const built = createSpecies({ id: "sp", atoms: [atom("na1", "Na", { formalCharge: 1 })] });
    expect(built.bonds).toEqual([]);
  });

  it("omits label and declaredTorsions rather than storing undefined", () => {
    const built = createSpecies({ id: "sp", atoms: [] });
    expect("label" in built).toBe(false);
    expect("declaredTorsions" in built).toBe(false);
  });

  it("keeps a label and declared torsions when given", () => {
    const built = createSpecies({
      id: "sp",
      label: "ethanol",
      atoms: ethanol().atoms,
      bonds: ethanol().bonds,
      declaredTorsions: [
        {
          atoms: ["c1", "c2", "o1", "c1"],
          degrees: 180,
          justification: "anti periplanar, from the authored conformer",
        },
      ],
    });
    expect(built.label).toBe("ethanol");
    expect(built.declaredTorsions).toHaveLength(1);
    expect(built.declaredTorsions?.[0]?.degrees).toBe(180);
  });

  it("copies the atom and bond lists rather than aliasing them", () => {
    const atoms = [atom("c1", "C")];
    const bonds: ReturnType<typeof bond>[] = [];
    const built = createSpecies({ id: "sp", atoms, bonds });
    atoms.length = 0;
    expect(built.atoms).toHaveLength(1);
    expect(Object.isFrozen(built.atoms)).toBe(true);
    expect(Object.isFrozen(built.bonds)).toBe(true);
  });

  it("does not enforce connectivity at construction", () => {
    // Deliberate, and the reason connectedComponentCount exists as a separate function:
    // a constructor that threw would make the broken fixture unbuildable, and a check
    // that can never be shown to fail is not evidence.
    const twoFragments = species("sp", [atom("c1", "C"), atom("c2", "C")]);
    expect(twoFragments.atoms).toHaveLength(2);
    expect(connectedComponentCount(twoFragments)).toBe(2);
  });
});

describe("finding atoms and bonds", () => {
  it("finds an atom by id and returns undefined when there is none", () => {
    expect(findAtom(ethanol(), "o1")?.element).toBe("O");
    expect(findAtom(ethanol(), "n1")).toBeUndefined();
  });

  it("throws from requireAtom, naming both the species and the atom", () => {
    expect(requireAtom(ethanol(), "c2").id).toBe("c2");
    expect(() => requireAtom(ethanol(), "n1")).toThrow(/sp-ethanol/);
    expect(() => requireAtom(ethanol(), "n1")).toThrow(/n1/);
  });

  it("finds a bond by id and returns undefined when there is none", () => {
    expect(findBond(ethanol(), "b2")?.order).toBe(1);
    expect(findBond(ethanol(), "b9")).toBeUndefined();
  });

  it("throws from requireBond, naming both the species and the bond", () => {
    expect(requireBond(ethanol(), "b1").id).toBe("b1");
    expect(() => requireBond(ethanol(), "b9")).toThrow(/sp-ethanol/);
    expect(() => requireBond(ethanol(), "b9")).toThrow(/b9/);
  });
});

describe("findBondBetween", () => {
  it("finds the bond whichever way round the two atoms are named", () => {
    expect(findBondBetween(ethanol(), "c2", "o1")?.id).toBe("b2");
    expect(findBondBetween(ethanol(), "o1", "c2")?.id).toBe("b2");
  });

  it("is undefined for two atoms that are not bonded", () => {
    expect(findBondBetween(ethanol(), "c1", "o1")).toBeUndefined();
  });

  it("is undefined for an atom that is not in the species", () => {
    expect(findBondBetween(ethanol(), "c1", "n1")).toBeUndefined();
  });
});

describe("bondsAt and neighborIds", () => {
  it("returns every bond touching an atom", () => {
    expect(bondsAt(ethanol(), "c2").map((b) => b.id)).toEqual(["b1", "b2"]);
    expect(bondsAt(ethanol(), "c1").map((b) => b.id)).toEqual(["b1"]);
  });

  it("is empty for an atom with no bonds", () => {
    expect(bondsAt(species("sp", [atom("na1", "Na")]), "na1")).toEqual([]);
  });

  it("names the far end of every bond, never the atom itself", () => {
    expect(neighborIds(ethanol(), "c2")).toEqual(["c1", "o1"]);
    expect(neighborIds(ethanol(), "o1")).toEqual(["c2"]);
    expect(neighborIds(ethanol(), "c2")).not.toContain("c2");
  });

  it("does not include implicit hydrogens, which have no id", () => {
    expect(neighborIds(chloromethane(), "c1")).toEqual(["cl1"]);
  });
});

describe("danglingBondIds", () => {
  it("is empty for a well formed species", () => {
    expect(danglingBondIds(ethanol())).toEqual([]);
  });

  it("names a bond whose first end is missing", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "ghost", "c1")]);
    expect(danglingBondIds(broken)).toEqual(["b1"]);
  });

  it("names a bond whose second end is missing", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "c1", "ghost")]);
    expect(danglingBondIds(broken)).toEqual(["b1"]);
  });

  it("names every dangling bond, not just the first", () => {
    const broken = species(
      "sp",
      [atom("c1", "C")],
      [bond("b1", "c1", "ghost"), bond("b2", "other", "c1")],
    );
    expect(danglingBondIds(broken)).toEqual(["b1", "b2"]);
  });
});

describe("connectedComponentCount", () => {
  it("is zero for a species with no atoms", () => {
    expect(connectedComponentCount(species("sp", []))).toBe(0);
  });

  it("is one for a single unbonded atom", () => {
    expect(connectedComponentCount(species("sp", [atom("na1", "Na")]))).toBe(1);
  });

  it("is one for a connected molecule", () => {
    expect(connectedComponentCount(ethanol())).toBe(1);
  });

  it("counts each disconnected fragment", () => {
    const packed = species(
      "sp",
      [atom("c1", "C"), atom("c2", "C"), atom("na1", "Na")],
      [bond("b1", "c1", "c2")],
    );
    expect(connectedComponentCount(packed)).toBe(2);
  });

  it("walks through a chain rather than only counting direct neighbours", () => {
    // A traversal that stopped at depth one would report four fragments here.
    const chain = species(
      "sp",
      [atom("c1", "C"), atom("c2", "C"), atom("c3", "C"), atom("c4", "C")],
      [bond("b1", "c1", "c2"), bond("b2", "c2", "c3"), bond("b3", "c3", "c4")],
    );
    expect(connectedComponentCount(chain)).toBe(1);
  });

  it("traverses a bond in both directions", () => {
    // The adjacency map is filled from both ends. Filling it from one would make the
    // count depend on the order the atoms happen to be listed in.
    const reversed = species(
      "sp",
      [atom("c1", "C"), atom("c2", "C")],
      [bond("b1", "c2", "c1")],
    );
    expect(connectedComponentCount(reversed)).toBe(1);
  });

  it("does not loop forever on a ring", () => {
    const cyclopropane = species(
      "sp",
      [
        atom("c1", "C", { implicitHydrogens: 2 }),
        atom("c2", "C", { implicitHydrogens: 2 }),
        atom("c3", "C", { implicitHydrogens: 2 }),
      ],
      [bond("b1", "c1", "c2"), bond("b2", "c2", "c3"), bond("b3", "c3", "c1")],
    );
    expect(connectedComponentCount(cyclopropane)).toBe(1);
  });

  it("ignores a bond naming an atom the species does not have", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "c1", "ghost")]);
    expect(connectedComponentCount(broken)).toBe(1);
  });
});

