import { describe, expect, it } from "vitest";

import {
  approximateMass,
  atomKey,
  bondOrderSumAt,
  conservedTotals,
  derivedFormalCharge,
  molecularFormula,
  nuclideCounts,
  nuclideCountsOfMany,
  nuclideDifference,
  speciesCharge,
  valenceElectronCount,
  valenceElectronsAround,
} from "../src/bookkeeping.ts";
import { createState } from "../src/state.ts";
import { atom, bond, chloromethane, hydroxide, member, methane, species, state } from "./helpers.ts";

const acetone = () => species(
  "sp-acetone",
  [
    atom("c1", "C", { implicitHydrogens: 3 }),
    atom("c2", "C"),
    atom("c3", "C", { implicitHydrogens: 3 }),
    atom("o1", "O", { lonePairs: 2 }),
  ],
  [bond("b1", "c1", "c2"), bond("b2", "c2", "c3"), bond("b3", "c2", "o1", 2)],
);

describe("nuclideCounts", () => {
  it("counts implicit hydrogens as real atoms", () => {
    // VERIFICATION.md S5: a proton transfer that changes only implicit hydrogen counts
    // touches no bond, so a mass count walking the explicit atom list reports
    // conservation while a proton has quietly appeared or vanished.
    expect(nuclideCounts(methane())).toEqual({ C: 1, H: 4 });
  });

  it("does not add a hydrogen entry when there are none", () => {
    expect(nuclideCounts(species("sp", [atom("cl1", "Cl", { lonePairs: 4 })]))).toEqual({ Cl: 1 });
  });

  it("sums implicit hydrogens across atoms", () => {
    expect(nuclideCounts(acetone())).toEqual({ C: 3, O: 1, H: 6 });
  });

  it("keys a labelled nuclide separately from its element", () => {
    const labelled = species("sp", [
      atom("c1", "C", { isotope: 13, implicitHydrogens: 1 }),
      atom("c2", "C"),
    ]);
    expect(nuclideCounts(labelled)).toEqual({ "[13C]": 1, C: 1, H: 1 });
  });

  it("is empty for a species with no atoms", () => {
    expect(nuclideCounts(species("sp", []))).toEqual({});
  });
});

describe("nuclideCountsOfMany", () => {
  it("adds the counts of every species rather than replacing them", () => {
    expect(nuclideCountsOfMany([methane("a"), methane("b")])).toEqual({ C: 2, H: 8 });
  });

  it("merges different species into one multiset", () => {
    expect(nuclideCountsOfMany([chloromethane(), hydroxide()])).toEqual({
      C: 1,
      Cl: 1,
      O: 1,
      H: 4,
    });
  });

  it("is empty for an empty list", () => {
    expect(nuclideCountsOfMany([])).toEqual({});
  });
});

describe("nuclideDifference", () => {
  it("is empty when the two multisets match exactly", () => {
    expect(nuclideDifference({ C: 1, H: 4 }, { C: 1, H: 4 })).toEqual({});
  });

  it("reports the signed change, after minus before", () => {
    expect(nuclideDifference({ C: 1, H: 4 }, { C: 1, H: 3 })).toEqual({ H: -1 });
    expect(nuclideDifference({ C: 1, H: 3 }, { C: 1, H: 4 })).toEqual({ H: 1 });
  });

  it("reports a nuclide present on only one side", () => {
    expect(nuclideDifference({ C: 1 }, { C: 1, Cl: 1 })).toEqual({ Cl: 1 });
    expect(nuclideDifference({ C: 1, Cl: 1 }, { C: 1 })).toEqual({ Cl: -1 });
  });

  it("omits keys that did not change, so the difference reads as a diff", () => {
    expect(nuclideDifference({ C: 3, O: 1, H: 6 }, { C: 3, O: 1, H: 7 })).toEqual({ H: 1 });
  });
});

describe("bondOrderSumAt", () => {
  it("counts implicit hydrogens as order one bonds", () => {
    // Forgetting this term makes every methyl group look like a carbanion.
    expect(bondOrderSumAt(methane(), "c1")).toBe(4);
  });

  it("counts a double bond as two", () => {
    expect(bondOrderSumAt(acetone(), "c2")).toBe(4);
    expect(bondOrderSumAt(acetone(), "o1")).toBe(2);
  });

  it("counts explicit bonds and implicit hydrogens together", () => {
    expect(bondOrderSumAt(acetone(), "c1")).toBe(4);
    expect(bondOrderSumAt(chloromethane(), "c1")).toBe(4);
  });

  it("is zero for a bare ion", () => {
    expect(bondOrderSumAt(species("sp", [atom("na1", "Na", { formalCharge: 1 })]), "na1")).toBe(0);
  });

  it("throws for an atom the species does not have", () => {
    expect(() => bondOrderSumAt(acetone(), "n1")).toThrow(/n1/);
  });
});

describe("derivedFormalCharge", () => {
  it("is zero on a neutral carbon with four bonds", () => {
    expect(derivedFormalCharge(methane(), "c1")).toBe(0);
  });

  it("is minus one on hydroxide oxygen", () => {
    // 6 valence - 6 nonbonding - 1 bond order = -1.
    expect(derivedFormalCharge(hydroxide(), "o1")).toBe(-1);
  });

  it("is plus one on a protonated carbonyl oxygen", () => {
    const protonated = species(
      "sp",
      [atom("c2", "C", { implicitHydrogens: 2 }), atom("o1", "O", { lonePairs: 1, implicitHydrogens: 1, formalCharge: 1 })],
      [bond("b1", "c2", "o1", 2)],
    );
    // 6 valence - 2 nonbonding - 3 bond order = +1.
    expect(derivedFormalCharge(protonated, "o1")).toBe(1);
  });

  it("is plus one on a carbocation carbon", () => {
    const cation = species("sp", [atom("c1", "C", { formalCharge: 1, implicitHydrogens: 3 })]);
    expect(derivedFormalCharge(cation, "c1")).toBe(1);
  });

  it("reports what the structure implies even when the declaration disagrees", () => {
    // The disagreement is the signal. Deriving the charge silently would delete it, and
    // formal_charge_disagrees_with_structure could never fire.
    const wrong = species("sp", [atom("c1", "C", { formalCharge: 3, implicitHydrogens: 4 })]);
    expect(derivedFormalCharge(wrong, "c1")).toBe(0);
    expect(wrong.atoms[0]?.formalCharge).toBe(3);
  });
});

describe("valenceElectronsAround", () => {
  it("counts bonding electrons in full at both ends, the octet convention", () => {
    // Not the formal charge convention, which splits them. Mixing the two is a classic
    // source of a check that fires on correct structures.
    expect(valenceElectronsAround(methane(), "c1")).toBe(8);
  });

  it("counts lone pairs and bonds together", () => {
    expect(valenceElectronsAround(hydroxide(), "o1")).toBe(8);
    expect(valenceElectronsAround(acetone(), "o1")).toBe(8);
  });

  it("reports six around neutral boron, which is legal and not an error", () => {
    const borane = species("sp", [atom("b1", "B", { implicitHydrogens: 3 })]);
    expect(valenceElectronsAround(borane, "b1")).toBe(6);
  });

  it("reports ten around a hypervalent phosphorus, above the period two ceiling", () => {
    const pentavalent = species(
      "sp",
      [
        atom("p1", "P"),
        atom("f1", "F", { lonePairs: 3 }),
        atom("f2", "F", { lonePairs: 3 }),
        atom("f3", "F", { lonePairs: 3 }),
        atom("f4", "F", { lonePairs: 3 }),
        atom("f5", "F", { lonePairs: 3 }),
      ],
      [
        bond("b1", "p1", "f1"),
        bond("b2", "p1", "f2"),
        bond("b3", "p1", "f3"),
        bond("b4", "p1", "f4"),
        bond("b5", "p1", "f5"),
      ],
    );
    expect(valenceElectronsAround(pentavalent, "p1")).toBe(10);
  });
});

describe("speciesCharge", () => {
  it("sums declared formal charges", () => {
    expect(speciesCharge(hydroxide())).toBe(-1);
    expect(speciesCharge(methane())).toBe(0);
  });

  it("cancels a plus and a minus inside one species, as in a zwitterion", () => {
    const zwitterion = species("sp", [
      atom("n1", "N", { formalCharge: 1 }),
      atom("o1", "O", { formalCharge: -1, lonePairs: 3 }),
    ]);
    expect(speciesCharge(zwitterion)).toBe(0);
  });

  it("is zero for a species with no atoms", () => {
    expect(speciesCharge(species("sp", []))).toBe(0);
  });
});

describe("valenceElectronCount", () => {
  it("counts an implicit hydrogen's electron", () => {
    expect(valenceElectronCount(methane())).toBe(8);
  });

  it("subtracts the charge, so a cation has one electron fewer", () => {
    const cation = species("sp", [atom("c1", "C", { formalCharge: 1, implicitHydrogens: 3 })]);
    expect(valenceElectronCount(cation)).toBe(6);
  });

  it("adds an electron for an anion", () => {
    // Hydroxide: 6 for oxygen plus 1 for the hydrogen, minus a charge of -1, is 8.
    expect(valenceElectronCount(hydroxide())).toBe(8);
  });
});

describe("conservedTotals", () => {
  const sodium = species("sp-sodium", [atom("na1", "Na", { formalCharge: 1 })]);
  const withSpectator = createState({
    id: "st",
    members: [member(chloromethane(), "substrate"), member(sodium, "counterion")],
    spectators: [
      {
        speciesId: "sp-sodium",
        reason: "unreacting_counterion",
        justification: "never touched by any arrow in this mechanism",
        declaredBy: "test",
      },
    ],
  });

  it("excludes spectators by default, which is what declaring one means", () => {
    const totals = conservedTotals(withSpectator);
    expect(totals.countedSpeciesIds).toEqual(["sp-chloromethane"]);
    expect(totals.charge).toBe(0);
    expect(totals.nuclides).toEqual({ C: 1, Cl: 1, H: 3 });
  });

  it("includes spectators when asked, which is what an adversary wants", () => {
    const totals = conservedTotals(withSpectator, { includeSpectators: true });
    expect(totals.countedSpeciesIds).toEqual(["sp-chloromethane", "sp-sodium"]);
    expect(totals.charge).toBe(1);
    expect(totals.nuclides).toEqual({ C: 1, Cl: 1, H: 3, Na: 1 });
  });

  it("treats an omitted option object the same as an absent flag", () => {
    expect(conservedTotals(withSpectator).charge).toBe(
      conservedTotals(withSpectator, {}).charge,
    );
  });

  it("treats includeSpectators false as excluding them", () => {
    expect(conservedTotals(withSpectator, { includeSpectators: false }).countedSpeciesIds).toEqual([
      "sp-chloromethane",
    ]);
  });

  it("sums charge and electrons across the whole multiset", () => {
    // The system boundary rule. Charge is conserved over everything present, not over
    // the substrate, which is why a protonation only balances when the acid is in scope.
    const both = state("st", [member(chloromethane()), member(hydroxide())]);
    const totals = conservedTotals(both);
    expect(totals.charge).toBe(-1);
    expect(totals.valenceElectrons).toBe(14 + 8);
    expect(totals.nuclides).toEqual({ C: 1, Cl: 1, O: 1, H: 4 });
  });

  it("freezes the totals and the counted species list", () => {
    const totals = conservedTotals(withSpectator);
    expect(Object.isFrozen(totals)).toBe(true);
    expect(Object.isFrozen(totals.countedSpeciesIds)).toBe(true);
  });
});

describe("display helpers, which conservation must never use", () => {
  it("gives an approximate mass that includes implicit hydrogens", () => {
    const mass = approximateMass(methane());
    expect(mass).toBeCloseTo(12.011 + 4 * 1.008, 6);
  });

  it("uses the mass number for a labelled atom", () => {
    expect(approximateMass(species("sp", [atom("h1", "H", { isotope: 2 })]))).toBeCloseTo(2, 6);
  });

  it("writes a formula in Hill order, carbon then hydrogen then the rest", () => {
    expect(molecularFormula(acetone())).toBe("C3H6O");
    expect(molecularFormula(chloromethane())).toBe("CH3Cl");
  });

  it("omits the count when there is exactly one of an element", () => {
    expect(molecularFormula(hydroxide())).toBe("HO");
  });

  it("sorts the non carbon non hydrogen elements alphabetically", () => {
    const mixed = species("sp", [atom("s1", "S"), atom("br1", "Br"), atom("n1", "N")]);
    expect(molecularFormula(mixed)).toBe("BrNS");
  });

  it("folds an isotope into its element, so a formula is not an identity", () => {
    const labelled = species("sp", [atom("c1", "C", { isotope: 13, implicitHydrogens: 4 })]);
    expect(molecularFormula(labelled)).toBe("CH4");
  });

  it("is an empty string for a species with no atoms", () => {
    expect(molecularFormula(species("sp", []))).toBe("");
  });
});

describe("atomKey", () => {
  it("is the atom's nuclide key", () => {
    expect(atomKey(atom("c1", "C"))).toBe("C");
    expect(atomKey(atom("h1", "H", { isotope: 2 }))).toBe("[2H]");
  });
});

test/state.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  allAtoms,
  atomsAreBonded,
  createState,
  duplicateAtomIds,
  duplicateSpeciesIds,
  findAtomInState,
  findBondInState,
  findMember,
  findSpecies,
  isSpectator,
  membersWithRole,
  orphanSpectatorDeclarations,
  participatingMembers,
  spectatorDeclarationFor,
  spectatorMembers,
  speciesIdOccurrences,
  type SpectatorDeclaration,
} from "../src/state.ts";
import { atom, bond, chloromethane, hydroxide, member, species, state } from "./helpers.ts";

const sodium = () => species("sp-sodium", [atom("na1", "Na", { formalCharge: 1 })]);

const spectatorDeclaration: SpectatorDeclaration = {
  speciesId: "sp-sodium",
  reason: "unreacting_counterion",
  justification: "sodium is a spectator counterion throughout this displacement",
  declaredBy: "test",
};

const sn2 = () => createState({
  id: "st-0",
  members: [
    member(chloromethane(), "substrate"),
    member(hydroxide(), "nucleophile"),
    member(sodium(), "counterion"),
  ],
  spectators: [spectatorDeclaration],
});

describe("createState", () => {
  it("defaults spectators to an empty list", () => {
    const bare = createState({ id: "st", members: [] });
    expect(bare.spectators).toEqual([]);
  });

  it("copies both lists rather than aliasing them, and freezes the result", () => {
    const members = [member(chloromethane())];
    const built = createState({ id: "st", members });
    members.length = 0;
    expect(built.members).toHaveLength(1);
    expect(Object.isFrozen(built)).toBe(true);
    expect(Object.isFrozen(built.members)).toBe(true);
    expect(Object.isFrozen(built.spectators)).toBe(true);
  });
});

describe("the system boundary", () => {
  it("knows which species are declared spectators", () => {
    expect(isSpectator(sn2(), "sp-sodium")).toBe(true);
    expect(isSpectator(sn2(), "sp-hydroxide")).toBe(false);
  });

  it("hands back the declaration itself, with the reason and the author", () => {
    // CLAUDE.md: declaring a spectator is an explicit, recorded act that a validator can
    // see and an adversary can attack. That is only true if the record is retrievable.
    const found = spectatorDeclarationFor(sn2(), "sp-sodium");
    expect(found?.reason).toBe("unreacting_counterion");
    expect(found?.justification.length).toBeGreaterThan(0);
    expect(found?.declaredBy).toBe("test");
    expect(spectatorDeclarationFor(sn2(), "sp-hydroxide")).toBeUndefined();
  });

  it("excludes spectators from the participating members and includes them nowhere else", () => {
    expect(participatingMembers(sn2()).map((m) => m.species.id)).toEqual([
      "sp-chloromethane",
      "sp-hydroxide",
    ]);
    expect(spectatorMembers(sn2()).map((m) => m.species.id)).toEqual(["sp-sodium"]);
  });

  it("partitions the members between participating and spectating with nothing lost", () => {
    expect(participatingMembers(sn2()).length + spectatorMembers(sn2()).length).toBe(
      sn2().members.length,
    );
  });

  it("names a declaration that points at a species not in the state", () => {
    const orphaned = createState({
      id: "st",
      members: [member(chloromethane())],
      spectators: [{ ...spectatorDeclaration, speciesId: "sp-absent" }],
    });
    expect(orphanSpectatorDeclarations(orphaned).map((d) => d.speciesId)).toEqual(["sp-absent"]);
    expect(orphanSpectatorDeclarations(sn2())).toEqual([]);
  });
});

describe("lookups across the multiset", () => {
  it("finds a species and its membership by id", () => {
    expect(findSpecies(sn2(), "sp-hydroxide")?.id).toBe("sp-hydroxide");
    expect(findSpecies(sn2(), "sp-absent")).toBeUndefined();
    expect(findMember(sn2(), "sp-hydroxide")?.role).toBe("nucleophile");
    expect(findMember(sn2(), "sp-absent")).toBeUndefined();
  });

  it("finds an atom in whichever species holds it, and reports both", () => {
    // Atom ids are unique across the whole state, which is what lets an arrow name a
    // source in one molecule and a sink in another without carrying a species id.
    const located = findAtomInState(sn2(), "o1");
    expect(located?.species.id).toBe("sp-hydroxide");
    expect(located?.atom.element).toBe("O");
    expect(findAtomInState(sn2(), "n1")).toBeUndefined();
  });

  it("finds a bond in whichever species holds it", () => {
    const located = findBondInState(sn2(), "b1");
    expect(located?.species.id).toBe("sp-chloromethane");
    expect(located?.bond.a).toBe("c1");
    expect(findBondInState(sn2(), "b9")).toBeUndefined();
  });

  it("lists every atom in the state, spectators included", () => {
    expect(allAtoms(sn2()).map((a) => a.id).sort()).toEqual(["c1", "cl1", "na1", "o1"]);
  });

  it("filters members by role", () => {
    expect(membersWithRole(sn2(), "nucleophile").map((m) => m.species.id)).toEqual(["sp-hydroxide"]);
    expect(membersWithRole(sn2(), "solvent")).toEqual([]);
  });
});

describe("atomsAreBonded", () => {
  it("is true for two atoms joined inside one species", () => {
    expect(atomsAreBonded(sn2(), "c1", "cl1")).toBe(true);
    expect(atomsAreBonded(sn2(), "cl1", "c1")).toBe(true);
  });

  it("is false for two atoms in different species", () => {
    // The adjacency test arrow legality turns on. An arrow reaching from one molecule
    // into another has to form a bond; it cannot travel along one that is not there.
    expect(atomsAreBonded(sn2(), "o1", "c1")).toBe(false);
  });

  it("is false for an atom and itself, which is not a bond", () => {
    expect(atomsAreBonded(sn2(), "c1", "c1")).toBe(false);
  });

  it("is false for an atom that is not in the state", () => {
    expect(atomsAreBonded(sn2(), "c1", "ghost")).toBe(false);
  });
});

describe("duplicate ids", () => {
  it("finds no duplicates in a well formed state", () => {
    expect(duplicateAtomIds(sn2())).toEqual([]);
    expect(duplicateSpeciesIds(sn2())).toEqual([]);
  });

  it("names an atom id used in two species", () => {
    const clash = state("st", [
      member(species("sp-a", [atom("c1", "C")])),
      member(species("sp-b", [atom("c1", "C")])),
    ]);
    expect(duplicateAtomIds(clash)).toEqual(["c1"]);
  });

  it("reports a repeated atom id once, however many times it repeats", () => {
    const clash = state("st", [
      member(species("sp-a", [atom("c1", "C")])),
      member(species("sp-b", [atom("c1", "C")])),
      member(species("sp-c", [atom("c1", "C")])),
    ]);
    expect(duplicateAtomIds(clash)).toEqual(["c1"]);
  });

  it("names a species id used by two members", () => {
    // The Phase 0 adversary finding: findSpecies resolves to whichever member is first,
    // so the second copy is invisible to every lookup while still counting toward every
    // total. One half of the engine sees it and the other half does not.
    const clash = state("st", [
      member(species("sp-water", [atom("o1", "O")])),
      member(species("sp-water", [atom("o2", "O")])),
    ]);
    expect(duplicateSpeciesIds(clash)).toEqual(["sp-water"]);
  });

  it("sorts duplicate species ids, so a failure report is stable between runs", () => {
    const clash = state("st", [
      member(species("sp-zeta", [atom("z1", "O")])),
      member(species("sp-alpha", [atom("a1", "O")])),
      member(species("sp-zeta", [atom("z2", "O")])),
      member(species("sp-alpha", [atom("a2", "O")])),
    ]);
    expect(duplicateSpeciesIds(clash)).toEqual(["sp-alpha", "sp-zeta"]);
  });
});

describe("speciesIdOccurrences", () => {
  it("is one for a species present once", () => {
    expect(speciesIdOccurrences(sn2(), "sp-hydroxide")).toBe(1);
  });

  it("is zero for a species that is not there", () => {
    expect(speciesIdOccurrences(sn2(), "sp-absent")).toBe(0);
  });

  it("counts every member carrying the id", () => {
    const clash = state("st", [
      member(species("sp-water", [atom("o1", "O")])),
      member(species("sp-water", [atom("o2", "O")])),
    ]);
    expect(speciesIdOccurrences(clash, "sp-water")).toBe(2);
  });
});

test/deltas-shape.test.ts.source:
import { describe, expect, it } from "vitest";

import { createArrow, fromLonePair, toAtom } from "../src/arrows.ts";
import { declaredDeltas, deltaMismatches, observedDeltas } from "../src/deltas.ts";
import { atom, bond, member, species, state } from "./helpers.ts";

/**
 * Which entries a delta set keeps, and what a mismatch points at.
 *
 * `assemble` drops any atom whose three counters are all zero and any bond pair whose
 * electron change is zero. That filter is the difference between a delta set that reads
 * as a diff and one that lists every atom in the flask, and each of its three clauses
 * needs its own case: an atom that changed in only one of the three would be dropped by
 * a filter missing that clause, and nothing else in the suite would notice.
 */

describe("assemble keeps an atom that changed in exactly one way", () => {
  it("keeps an atom whose only change is nonbonding electrons", () => {
    const from = state("st-0", [member(species("sp", [atom("o1", "O", { lonePairs: 2 })]))]);
    const to = state("st-1", [member(species("sp", [atom("o1", "O", { lonePairs: 3 })]))]);
    expect(observedDeltas(from, to).atoms).toEqual([
      { atomId: "o1", nonbondingElectrons: 2, implicitHydrogens: 0, formalCharge: 0 },
    ]);
  });

  it("keeps an atom whose only change is an implicit hydrogen count", () => {
    // The S5 case in isolation. Nothing bonded, nothing charged, one undrawn hydrogen
    // gone. A filter that only looked at nonbonding electrons would drop this entry and
    // the mismatch that catches the bug would never be produced.
    const from = state("st-0", [
      member(species("sp", [atom("o1", "O", { lonePairs: 2, implicitHydrogens: 1 })])),
    ]);
    const to = state("st-1", [
      member(species("sp", [atom("o1", "O", { lonePairs: 2, implicitHydrogens: 0 })])),
    ]);
    expect(observedDeltas(from, to).atoms).toEqual([
      { atomId: "o1", nonbondingElectrons: 0, implicitHydrogens: -1, formalCharge: 0 },
    ]);
  });

  it("keeps an atom whose only change is a declared formal charge", () => {
    // A charge relabelled with no electron change at all. It is carried, never asserted
    // here, but dropping it would hide a structure whose declaration was edited alone.
    const from = state("st-0", [
      member(species("sp", [atom("c1", "C", { implicitHydrogens: 3, formalCharge: 0 })])),
    ]);
    const to = state("st-1", [
      member(species("sp", [atom("c1", "C", { implicitHydrogens: 3, formalCharge: 1 })])),
    ]);
    expect(observedDeltas(from, to).atoms).toEqual([
      { atomId: "c1", nonbondingElectrons: 0, implicitHydrogens: 0, formalCharge: 1 },
    ]);
  });

  it("drops an atom that did not change in any of the three", () => {
    const same = state("st", [member(species("sp", [atom("c1", "C", { implicitHydrogens: 4 })]))]);
    expect(observedDeltas(same, same).atoms).toEqual([]);
  });

  it("drops a bond whose electron count did not change", () => {
    // Every bond in the flask appears in both maps. Without the zero filter the set would
    // list the whole structure and a reader would have to find the two lines that matter.
    const same = state("st", [
      member(
        species(
          "sp",
          [atom("c1", "C", { implicitHydrogens: 3 }), atom("cl1", "Cl", { lonePairs: 3 })],
          [bond("b1", "c1", "cl1")],
        ),
      ),
    ]);
    expect(observedDeltas(same, same).bonds).toEqual([]);
  });
});

describe("a mismatch says exactly what it is about", () => {
  const from = state("st-0", [
    member(species("sp", [atom("o1", "O", { lonePairs: 3 }), atom("c1", "C")])),
  ]);
  const to = state("st-1", [
    member(species("sp", [atom("o1", "O", { lonePairs: 3 }), atom("c1", "C")])),
  ]);

  it("points at the atom by id when nonbonding electrons disagree", () => {
    const declared = declaredDeltas(
      [createArrow({ id: "a1", source: fromLonePair("o1"), sink: toAtom("c1") })],
      from,
    );
    const mismatches = deltaMismatches(declared, observedDeltas(from, to));
    const atOxygen = mismatches.find(
      (mismatch) => mismatch.target.kind === "atom" && mismatch.target.atomId === "o1",
    );
    expect(atOxygen?.target).toEqual({ kind: "atom", atomId: "o1" });
    expect(atOxygen?.quantity).toBe("nonbondingElectrons");
    expect(atOxygen?.declared).toBe(-2);
    expect(atOxygen?.observed).toBe(0);
  });

  it("points at the atom by id when an implicit hydrogen moved", () => {
    const protonated = state("st-0", [
      member(species("sp", [atom("o1", "O", { lonePairs: 2, implicitHydrogens: 1 })])),
    ]);
    const deprotonated = state("st-1", [
      member(species("sp", [atom("o1", "O", { lonePairs: 2, implicitHydrogens: 0 })])),
    ]);
    const mismatch = deltaMismatches(
      declaredDeltas([], protonated),
      observedDeltas(protonated, deprotonated),
    ).find((entry) => entry.quantity === "implicitHydrogens");
    expect(mismatch?.target).toEqual({ kind: "atom", atomId: "o1" });
  });
});

test/edit-invariants.test.ts.source:
import { describe, expect, it } from "vitest";

import { createSpecies } from "../src/species.ts";
import { createState, type SpectatorDeclaration } from "../src/state.ts";
import {
  declareSpectator,
  withAddedBond,
  withAtomPatch,
  withBondOrder,
  withBondStereo,
  withMember,
  withReplacedSpecies,
  withdrawSpectator,
} from "../src/edit.ts";
import { atom, bond, chloromethane, hydroxide, member, species, state } from "./helpers.ts";

/**
 * What an immutable edit must NOT touch.
 *
 * The tests in edit.test.ts check that each edit does its own job. These check the parts
 * that are easy to lose silently: optional fields carried through a rebuild, and the
 * "only this one" half of every edit that names a target. Mutation testing found both
 * groups unasserted, which is the same failure shape either way: an edit that quietly
 * applies to everything looks identical to a correct one on a one member state.
 */

const torsioned = () =>
  createSpecies({
    id: "sp-torsioned",
    label: "butane, anti",
    atoms: [
      atom("c1", "C", { implicitHydrogens: 3 }),
      atom("c2", "C", { implicitHydrogens: 2 }),
      atom("c3", "C", { implicitHydrogens: 2 }),
      atom("c4", "C", { implicitHydrogens: 3 }),
    ],
    bonds: [bond("b1", "c1", "c2"), bond("b2", "c2", "c3"), bond("b3", "c3", "c4")],
    declaredTorsions: [
      {
        atoms: ["c1", "c2", "c3", "c4"],
        degrees: 180,
        justification: "anti periplanar in the authored conformer",
      },
    ],
  });

describe("a rebuild carries the optional fields it did not touch", () => {
  it("keeps a declared torsion through an atom patch", () => {
    // A torsion is the only conformational evidence E2 has. Dropping it during an
    // unrelated edit would turn an authored anti periplanar geometry into an unstated one.
    const patched = withAtomPatch(torsioned(), "c1", { formalCharge: 1 });
    expect(patched.declaredTorsions).toHaveLength(1);
    expect(patched.declaredTorsions?.[0]?.degrees).toBe(180);
    expect(patched.declaredTorsions?.[0]?.justification.length).toBeGreaterThan(0);
  });

  it("keeps a label through an atom patch", () => {
    expect(withAtomPatch(torsioned(), "c1", { formalCharge: 1 }).label).toBe("butane, anti");
  });

  it("leaves a species with no label and no torsions without either field", () => {
    // The absent branch of the same two conditionals. A rebuild that wrote the key with
    // an undefined value would break exactOptionalPropertyTypes at every later read.
    const patched = withAtomPatch(chloromethane(), "cl1", { lonePairs: 4 });
    expect("label" in patched).toBe(false);
    expect("declaredTorsions" in patched).toBe(false);
  });

  it("leaves a bond with no stereo without the field after an order change", () => {
    const raised = withBondOrder(chloromethane(), "b1", 2);
    expect("stereo" in (raised.bonds[0] ?? {})).toBe(false);
  });
});

describe("a patch field set to zero still overrides", () => {
  it("applies an unpairedElectrons patch of zero, quenching a radical", () => {
    // `patch.x ?? atom.x` and `patch.x && atom.x` agree on every value except zero and
    // false, and zero is the value that matters here: a radical recombination sets the
    // unpaired count to zero and a truthiness test would silently keep the radical.
    const radical = species("sp", [atom("br1", "Br", { lonePairs: 3, unpairedElectrons: 1 })]);
    const quenched = withAtomPatch(radical, "br1", { unpairedElectrons: 0 });
    expect(quenched.atoms[0]?.unpairedElectrons).toBe(0);
  });

  it("applies a lonePairs patch of zero", () => {
    const quenched = withAtomPatch(hydroxide(), "o1", { lonePairs: 0 });
    expect(quenched.atoms[0]?.lonePairs).toBe(0);
  });

  it("applies an implicitHydrogens patch of zero", () => {
    const stripped = withAtomPatch(chloromethane(), "c1", { implicitHydrogens: 0 });
    expect(stripped.atoms.find((a) => a.id === "c1")?.implicitHydrogens).toBe(0);
  });

  it("applies a formalCharge patch of zero, which is how a cation is neutralised", () => {
    const cation = species("sp", [atom("c1", "C", { formalCharge: 1, implicitHydrogens: 3 })]);
    expect(withAtomPatch(cation, "c1", { formalCharge: 0 }).atoms[0]?.formalCharge).toBe(0);
  });
});

describe("an edit that names a target touches only that target", () => {
  it("sets stereo on the named bond only", () => {
    const twoBonds = species(
      "sp",
      [atom("c1", "C"), atom("c2", "C"), atom("c3", "C")],
      [bond("b1", "c1", "c2", 2), bond("b2", "c2", "c3", 2)],
    );
    const stereoed = withBondStereo(twoBonds, "b1", {
      kind: "doubleBond",
      reference: ["c1", "c3"],
      arrangement: "cis",
    });
    expect(stereoed.bonds[0]?.stereo).toBeDefined();
    expect("stereo" in (stereoed.bonds[1] ?? {})).toBe(false);
  });

  it("replaces the named species only, in a state with more than one member", () => {
    const both = state("st", [
      member(chloromethane(), "substrate"),
      member(hydroxide(), "nucleophile"),
    ]);
    const replaced = withReplacedSpecies(both, species("sp-chloromethane", [atom("c1", "C")]));
    expect(replaced.members[0]?.species.atoms).toHaveLength(1);
    expect(replaced.members[1]?.species.id).toBe("sp-hydroxide");
    expect(replaced.members[1]?.species.atoms).toHaveLength(1);
    expect(replaced.members[1]?.species.atoms[0]?.element).toBe("O");
  });

  it("refuses a duplicate member even when another member has a different id", () => {
    // `some` and `every` agree on a one member state and disagree here, which is the
    // shape of a duplicate guard that passes its own test and lets duplicates through in
    // the real corpus.
    const both = state("st", [
      member(chloromethane(), "substrate"),
      member(hydroxide(), "nucleophile"),
    ]);
    expect(() => withMember(both, member(hydroxide(), "reagent"))).toThrow(/sp-hydroxide/);
  });

  it("adds a member whose id is new even when other members exist", () => {
    const one = state("st", [member(chloromethane(), "substrate")]);
    expect(withMember(one, member(hydroxide(), "nucleophile")).members).toHaveLength(2);
  });

  it("refuses a duplicate bond id even when another bond has a different id", () => {
    const twoBonds = species(
      "sp",
      [atom("c1", "C"), atom("c2", "C"), atom("c3", "C")],
      [bond("b1", "c1", "c2"), bond("b2", "c2", "c3")],
    );
    expect(() => withAddedBond(twoBonds, bond("b1", "c1", "c3"))).toThrow(/b1/);
    expect(withAddedBond(twoBonds, bond("b3", "c1", "c3")).bonds).toHaveLength(3);
  });
});

describe("spectator declarations in a state with more than one member", () => {
  const declarationFor = (speciesId: string): SpectatorDeclaration => ({
    speciesId,
    reason: "unreacting_counterion",
    justification: "not touched by any arrow in this step",
    declaredBy: "test",
  });

  const twoMembers = () =>
    createState({
      id: "st",
      members: [member(chloromethane(), "substrate"), member(hydroxide(), "nucleophile")],
    });

  it("declares the named species when others are present", () => {
    const declared = declareSpectator(twoMembers(), declarationFor("sp-hydroxide"));
    expect(declared.spectators.map((d) => d.speciesId)).toEqual(["sp-hydroxide"]);
  });

  it("still refuses a species that is absent when other members are present", () => {
    expect(() => declareSpectator(twoMembers(), declarationFor("sp-absent"))).toThrow(
      /sp-absent/,
    );
  });

  it("refuses a second declaration when another species is already declared", () => {
    const declared = declareSpectator(twoMembers(), declarationFor("sp-hydroxide"));
    expect(() => declareSpectator(declared, declarationFor("sp-hydroxide"))).toThrow(/already/);
    expect(
      declareSpectator(declared, declarationFor("sp-chloromethane")).spectators,
    ).toHaveLength(2);
  });

  it("withdraws the named declaration and keeps every other one", () => {
    const declared = declareSpectator(
      declareSpectator(twoMembers(), declarationFor("sp-hydroxide")),
      declarationFor("sp-chloromethane"),
    );
    const withdrawn = withdrawSpectator(declared, "sp-hydroxide");
    expect(withdrawn.spectators.map((d) => d.speciesId)).toEqual(["sp-chloromethane"]);
    expect(withdrawn.members).toHaveLength(2);
  });
});

test/survivor-gaps.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  createArrow,
  fromBond,
  fromLonePair,
  fromSingleElectron,
  toAtom,
  toBondBetween,
} from "../src/arrows.ts";
import { atomPairKey, parseAtomPairKey } from "../src/bond.ts";
import { withAtomPatch, withoutMember } from "../src/edit.ts";
import { arrowLegalityFindings } from "../src/legality.ts";
import { connectedComponentCount } from "../src/species.ts";
import { createState, type SpectatorDeclaration } from "../src/state.ts";
import { atom, bond, chloromethane, hydroxide, member, species, state } from "./helpers.ts";

/**
 * Behaviour that nothing else in the suite asserted.
 *
 * Every case here was found by a surviving mutant, and each is written as the smallest
 * input that tells the two behaviours apart. They are grouped in one file because what
 * they have in common is how they were found, not what they are about.
 */

describe("a capacity finding names only the arrows that drew from THAT kind of source", () => {
  // An atom can carry a lone pair and an unpaired electron at once. A filter that only
  // matched on the atom id would fold a fishhook into a lone pair overdraw and send the
  // reader to an arrow that took nothing from the pair.
  const mixed = () =>
    state("st", [
      member(
        species("sp", [
          atom("o1", "O", { lonePairs: 1, unpairedElectrons: 1 }),
          atom("c1", "C"),
          atom("c2", "C"),
          atom("c3", "C"),
        ]),
      ),
    ]);

  it("keeps a fishhook out of a lone pair overdraw at the same atom", () => {
    const findings = arrowLegalityFindings(
      [
        createArrow({ id: "a1", source: fromLonePair("o1"), sink: toBondBetween("o1", "c1") }),
        createArrow({ id: "a2", source: fromLonePair("o1"), sink: toBondBetween("o1", "c2") }),
        createArrow({
          id: "a3",
          source: fromSingleElectron("o1"),
          sink: toBondBetween("o1", "c3"),
          electrons: 1,
        }),
      ],
      mixed(),
    );
    expect(findings.find((f) => f.rule === "lone_pairs_overdrawn")?.arrowId).toBe("a1 + a2");
  });

  it("keeps a lone pair arrow out of an unpaired electron overdraw at the same atom", () => {
    const findings = arrowLegalityFindings(
      [
        createArrow({
          id: "a1",
          source: fromSingleElectron("o1"),
          sink: toBondBetween("o1", "c1"),
          electrons: 1,
        }),
        createArrow({
          id: "a2",
          source: fromSingleElectron("o1"),
          sink: toBondBetween("o1", "c2"),
          electrons: 1,
        }),
        createArrow({ id: "a3", source: fromLonePair("o1"), sink: toBondBetween("o1", "c3") }),
      ],
      mixed(),
    );
    expect(findings.find((f) => f.rule === "unpaired_electrons_overdrawn")?.arrowId).toBe(
      "a1 + a2",
    );
  });
});

describe("an adjacency message lists both atoms of a bond source", () => {
  it("separates the two source atoms so the pivot that is missing is readable", () => {
    const branched = state("st", [
      member(
        species(
          "sp",
          [
            atom("c1", "C", { implicitHydrogens: 1 }),
            atom("c2", "C", { implicitHydrogens: 3 }),
            atom("c3", "C", { implicitHydrogens: 3 }),
          ],
          [bond("b1", "c1", "c2"), bond("b2", "c1", "c3")],
        ),
      ),
    ]);
    const finding = arrowLegalityFindings(
      [createArrow({ id: "a1", source: fromBond("b1"), sink: toAtom("c3") })],
      branched,
    )[0];
    expect(finding?.expected).toContain("the source site {c1, c2}");
    expect(finding?.expected).toContain("the sink site {c3}");
  });
});

describe("withoutMember withdraws only the departing species' own declaration", () => {
  it("keeps a spectator declaration about a species that is staying", () => {
    const declaration: SpectatorDeclaration = {
      speciesId: "sp-chloromethane",
      reason: "authored_simplification",
      justification: "outside the scope of this question",
      declaredBy: "test",
    };
    const both = createState({
      id: "st",
      members: [member(chloromethane(), "substrate"), member(hydroxide(), "nucleophile")],
      spectators: [declaration],
    });
    const shrunk = withoutMember(both, "sp-hydroxide");
    expect(shrunk.members.map((m) => m.species.id)).toEqual(["sp-chloromethane"]);
    expect(shrunk.spectators.map((d) => d.speciesId)).toEqual(["sp-chloromethane"]);
  });
});

describe("a patch that raises a count from zero still applies", () => {
  it("turns a closed shell atom into a radical", () => {
    // Homolysis writes an unpaired electron onto an atom that had none. `?? ` keeps the
    // patched 1; a truthiness test would read the atom's 0 and silently do nothing.
    const closedShell = species("sp", [atom("br1", "Br", { lonePairs: 3 })]);
    const radical = withAtomPatch(closedShell, "br1", { unpairedElectrons: 1 });
    expect(radical.atoms[0]?.unpairedElectrons).toBe(1);
  });

  it("adds a lone pair to an atom that had none", () => {
    const carbanion = withAtomPatch(chloromethane(), "c1", { lonePairs: 1, formalCharge: -1 });
    expect(carbanion.atoms.find((a) => a.id === "c1")?.lonePairs).toBe(1);
  });

  it("adds an implicit hydrogen to an atom that had none", () => {
    const protonated = withAtomPatch(chloromethane(), "cl1", { implicitHydrogens: 1 });
    expect(protonated.atoms.find((a) => a.id === "cl1")?.implicitHydrogens).toBe(1);
  });
});

describe("connectedComponentCount survives a dangling bond at either end", () => {
  it("ignores a bond whose first named atom is missing", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "ghost", "c1")]);
    expect(connectedComponentCount(broken)).toBe(1);
  });

  it("ignores a bond whose second named atom is missing", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "c1", "ghost")]);
    expect(connectedComponentCount(broken)).toBe(1);
  });

  it("ignores a bond with neither atom present", () => {
    const broken = species("sp", [atom("c1", "C")], [bond("b1", "gx", "gy")]);
    expect(connectedComponentCount(broken)).toBe(1);
  });
});

describe("atom pair keys round trip for any pair of ids", () => {
  it("round trips ids that sort either way", () => {
    for (const [a, b] of [
      ["c1", "cl1"],
      ["cl1", "c1"],
      ["a", "b"],
      ["b", "a"],
    ] as const) {
      expect(parseAtomPairKey(atomPairKey(a, b))).toEqual([a, b].sort());
    }
  });

  it("round trips a pair whose first id is empty", () => {
    // Not a chemistry case. It is the boundary of the separator search: an empty first id
    // puts the separator at index 0, and a guard written as `<= 0` would reject a key the
    // key builder itself produced.
    expect(parseAtomPairKey(atomPairKey("", "b"))).toEqual(["", "b"]);
  });
});

test/bond.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  atomPairKey,
  bondPairKey,
  bondTouches,
  createBond,
  otherEnd,
  parseAtomPairKey,
  type DoubleBondStereo,
} from "../src/bond.ts";

describe("createBond", () => {
  it("defaults to order one", () => {
    expect(createBond({ id: "b1", a: "c1", b: "c2" }).order).toBe(1);
  });

  it("keeps the order it was given", () => {
    expect(createBond({ id: "b1", a: "c1", b: "c2", order: 2 }).order).toBe(2);
    expect(createBond({ id: "b1", a: "c1", b: "c2", order: 3 }).order).toBe(3);
  });

  it("refuses a bond from an atom to itself", () => {
    // Not a chemistry judgement. A self bond makes atomPairKey degenerate and every
    // bond delta keyed on it meaningless, so it is refused at construction.
    expect(() => createBond({ id: "b1", a: "c1", b: "c1" })).toThrow(/c1/);
  });

  it("keeps the two ends in the order they were written", () => {
    const built = createBond({ id: "b1", a: "c1", b: "cl1" });
    expect(built.a).toBe("c1");
    expect(built.b).toBe("cl1");
  });

  it("omits stereo rather than storing undefined", () => {
    expect("stereo" in createBond({ id: "b1", a: "c1", b: "c2" })).toBe(false);
  });

  it("carries double bond stereo through untouched", () => {
    const stereo: DoubleBondStereo = {
      kind: "doubleBond",
      reference: ["c1", "c4"],
      arrangement: "cis",
    };
    expect(createBond({ id: "b1", a: "c2", b: "c3", order: 2, stereo }).stereo).toEqual(stereo);
  });

  it("freezes the result", () => {
    expect(Object.isFrozen(createBond({ id: "b1", a: "c1", b: "c2" }))).toBe(true);
  });
});

describe("atomPairKey", () => {
  it("is the same whichever end is written first", () => {
    // Bonds are matched across a step by this key, because a bond that forms had no id
    // in the previous state. An order sensitive key would report every formed bond as a
    // different bond depending on which end the author happened to type first.
    expect(atomPairKey("c1", "cl1")).toBe(atomPairKey("cl1", "c1"));
  });

  it("sorts the two ids", () => {
    expect(atomPairKey("c1", "cl1")).toBe("c1|cl1");
    expect(atomPairKey("cl1", "c1")).toBe("c1|cl1");
    expect(atomPairKey("b", "a")).toBe("a|b");
  });

  it("separates distinct pairs that share a prefix", () => {
    expect(atomPairKey("c1", "c10")).not.toBe(atomPairKey("c1", "c1"));
    expect(atomPairKey("a", "bc")).not.toBe(atomPairKey("ab", "c"));
  });

  it("reads a bond's key off the bond", () => {
    expect(bondPairKey(createBond({ id: "b1", a: "cl1", b: "c1" }))).toBe("c1|cl1");
  });
});

describe("parseAtomPairKey", () => {
  it("round trips a key back to its two ids in sorted order", () => {
    expect(parseAtomPairKey(atomPairKey("cl1", "c1"))).toEqual(["c1", "cl1"]);
  });

  it("splits on the first separator", () => {
    expect(parseAtomPairKey("a|b")).toEqual(["a", "b"]);
  });

  it("throws on a string that is not a key", () => {
    expect(() => parseAtomPairKey("c1c2")).toThrow(/c1c2/);
    expect(() => parseAtomPairKey("")).toThrow();
  });
});

describe("otherEnd", () => {
  const single = createBond({ id: "b1", a: "c1", b: "cl1" });

  it("returns the far end from either side", () => {
    expect(otherEnd(single, "c1")).toBe("cl1");
    expect(otherEnd(single, "cl1")).toBe("c1");
  });

  it("throws when the atom is not on the bond", () => {
    expect(() => otherEnd(single, "o1")).toThrow(/o1/);
  });
});

describe("bondTouches", () => {
  const single = createBond({ id: "b1", a: "c1", b: "cl1" });

  it("is true at both ends and false elsewhere", () => {
    expect(bondTouches(single, "c1")).toBe(true);
    expect(bondTouches(single, "cl1")).toBe(true);
    expect(bondTouches(single, "o1")).toBe(false);
  });
});

test/atom.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  atomNuclideKey,
  createAtom,
  nonbondingElectrons,
  nuclideKey,
  type TetrahedralStereo,
} from "../src/atom.ts";
import { IMPLICIT_HYDROGEN } from "../src/ids.ts";

describe("createAtom", () => {
  it("fills every count with zero rather than leaving it undefined", () => {
    const built = createAtom({ id: "c1", element: "C" });
    expect(built.formalCharge).toBe(0);
    expect(built.lonePairs).toBe(0);
    expect(built.unpairedElectrons).toBe(0);
    expect(built.implicitHydrogens).toBe(0);
  });

  it("keeps the values it was given", () => {
    const built = createAtom({
      id: "o1",
      element: "O",
      formalCharge: -1,
      lonePairs: 3,
      unpairedElectrons: 0,
      implicitHydrogens: 1,
    });
    expect(built.id).toBe("o1");
    expect(built.element).toBe("O");
    expect(built.formalCharge).toBe(-1);
    expect(built.lonePairs).toBe(3);
    expect(built.implicitHydrogens).toBe(1);
  });

  it("distinguishes an absent optional field from one set to undefined", () => {
    // exactOptionalPropertyTypes is on, and the whole reason the constructor spreads
    // conditionally instead of assigning. A field present and undefined survives
    // JSON round trips differently and reads as "declared, empty" rather than "absent".
    const plain = createAtom({ id: "c1", element: "C" });
    expect("isotope" in plain).toBe(false);
    expect("stereo" in plain).toBe(false);
    expect("geometry" in plain).toBe(false);
  });

  it("carries an isotope when one is given, so deuterium is not a separate element", () => {
    const deuterium = createAtom({ id: "h1", element: "H", isotope: 2 });
    expect(deuterium.element).toBe("H");
    expect(deuterium.isotope).toBe(2);
  });

  it("carries geometry and stereo through untouched", () => {
    const stereo: TetrahedralStereo = {
      kind: "tetrahedral",
      neighbors: ["a", "b", "c", IMPLICIT_HYDROGEN],
      parity: "clockwise",
    };
    const built = createAtom({
      id: "c1",
      element: "C",
      stereo,
      geometry: { x: 1, y: 2, z: 3 },
    });
    expect(built.stereo).toEqual(stereo);
    expect(built.geometry).toEqual({ x: 1, y: 2, z: 3 });
  });

  it("freezes the result, because readonly disappears at runtime", () => {
    const built = createAtom({ id: "c1", element: "C" });
    expect(Object.isFrozen(built)).toBe(true);
  });
});

describe("nonbondingElectrons", () => {
  it("counts a lone pair as two electrons", () => {
    expect(nonbondingElectrons(createAtom({ id: "o1", element: "O", lonePairs: 3 }))).toBe(6);
    expect(nonbondingElectrons(createAtom({ id: "o1", element: "O", lonePairs: 2 }))).toBe(4);
  });

  it("counts an unpaired electron as one", () => {
    expect(
      nonbondingElectrons(createAtom({ id: "c1", element: "C", unpairedElectrons: 1 })),
    ).toBe(1);
  });

  it("adds the two rather than taking whichever is larger", () => {
    // A bromine radical has three lone pairs and one unpaired electron: seven electrons,
    // not six and not one.
    const bromineRadical = createAtom({
      id: "br1",
      element: "Br",
      lonePairs: 3,
      unpairedElectrons: 1,
    });
    expect(nonbondingElectrons(bromineRadical)).toBe(7);
  });

  it("is zero for a closed shell atom with no lone pairs", () => {
    expect(nonbondingElectrons(createAtom({ id: "c1", element: "C" }))).toBe(0);
  });
});

describe("nuclide keys", () => {
  it("is the bare symbol at natural abundance", () => {
    expect(nuclideKey("C")).toBe("C");
    expect(nuclideKey("H")).toBe("H");
  });

  it("brackets the mass number when the atom is labelled", () => {
    expect(nuclideKey("H", 2)).toBe("[2H]");
    expect(nuclideKey("C", 13)).toBe("[13C]");
  });

  it("keeps a labelled nuclide distinct from its unlabelled element", () => {
    // Mass is conserved as a multiset of these keys. If deuterium and protium shared a
    // key, an isotope label could be lost across a step and mass would still balance,
    // which deletes every labelling experiment in the corpus.
    expect(nuclideKey("H", 2)).not.toBe(nuclideKey("H"));
    expect(nuclideKey("C", 13)).not.toBe(nuclideKey("C"));
  });

  it("reads the key off an atom the same way", () => {
    expect(atomNuclideKey(createAtom({ id: "c1", element: "C" }))).toBe("C");
    expect(atomNuclideKey(createAtom({ id: "h1", element: "H", isotope: 2 }))).toBe("[2H]");
  });
});

test/ids.test.ts.source:
import { describe, expect, it } from "vitest";

import {
  IMPLICIT_HYDROGEN,
  LONE_PAIR,
  RESERVED_ID_PREFIX,
  isImplicitHydrogenSlot,
  isLonePairSlot,
  isSentinelId,
} from "../src/ids.ts";

describe("reserved identifiers", () => {
  it("uses a prefix no real id would carry, and both sentinels use it", () => {
    expect(RESERVED_ID_PREFIX).toBe("@");
    expect(IMPLICIT_HYDROGEN.startsWith(RESERVED_ID_PREFIX)).toBe(true);
    expect(LONE_PAIR.startsWith(RESERVED_ID_PREFIX)).toBe(true);
  });

  it("keeps the two sentinels distinct", () => {
    // They fill different slots in a stereo neighbour list. One value for both would
    // make a pyramidal sulfoxide indistinguishable from a CH stereocenter.
    expect(IMPLICIT_HYDROGEN).not.toBe(LONE_PAIR);
  });
});

describe("isSentinelId", () => {
  it("is true for both sentinels", () => {
    expect(isSentinelId(IMPLICIT_HYDROGEN)).toBe(true);
    expect(isSentinelId(LONE_PAIR)).toBe(true);
  });

  it("is false for ordinary atom ids", () => {
    expect(isSentinelId("c1")).toBe(false);
    expect(isSentinelId("")).toBe(false);
    expect(isSentinelId("h1")).toBe(false);
  });

  it("keys on the prefix rather than on the two known values", () => {
    // A future sentinel must be caught by the same test a validator already runs.
    expect(isSentinelId("@somethingElse")).toBe(true);
  });

  it("looks at the start of the id, not anywhere in it", () => {
    expect(isSentinelId("c1@")).toBe(false);
    expect(isSentinelId("atom@implicitH")).toBe(false);
  });
});

describe("slot predicates", () => {
  it("match their own sentinel and nothing else", () => {
    expect(isImplicitHydrogenSlot(IMPLICIT_HYDROGEN)).toBe(true);
    expect(isImplicitHydrogenSlot(LONE_PAIR)).toBe(false);
    expect(isImplicitHydrogenSlot("h1")).toBe(false);

    expect(isLonePairSlot(LONE_PAIR)).toBe(true);
    expect(isLonePairSlot(IMPLICIT_HYDROGEN)).toBe(false);
    expect(isLonePairSlot("lp")).toBe(false);
  });

  it("compare exactly, so a near miss is not silently accepted", () => {
    expect(isImplicitHydrogenSlot("@implicith")).toBe(false);
    expect(isLonePairSlot("@lonepair")).toBe(false);
  });
});

